INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_2_math_u6_L02_basic#1','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',1,'mc','auto','막대그래프에서 막대의 길이가 길수록 무엇을 뜻하나요?',ARRAY['M5-2-u6-X18','M5-2-u6-X01']::text[],true,'{"seq":1,"concept":"M5-2-u6-C1","difficulty":1,"kind":"mc","stem":"막대그래프에서 막대의 길이가 길수록 무엇을 뜻하나요?","options":[{"t":"나타내는 수량이 많다","correct":true},{"t":"나타내는 수량이 적다","mis":"M5-2-u6-X18"},{"t":"평균이 작다","mis":"M5-2-u6-X01"},{"t":"조사한 사람이 적다","mis":"M5-2-u6-X18"}],"explanation":["막대그래프는 막대의 길이로 수량을 나타내요.","막대가 길수록 수량이 많고 짧을수록 적어요.","정답은 「나타내는 수량이 많다」예요."],"variant_rule":{"alt":[{"stem":"막대그래프에서 가장 짧은 막대는 무엇을 뜻하나요?","options":[{"t":"나타내는 수량이 가장 적다","correct":true},{"t":"나타내는 수량이 가장 많다","mis":"M5-2-u6-X18"},{"t":"평균과 같다","mis":"M5-2-u6-X02"},{"t":"자료가 잘못되었다","mis":"M5-2-u6-X18"}],"explanation":["막대그래프는 막대의 길이로 수량을 나타내요.","막대가 길수록 수량이 많고 짧을수록 적어요.","정답은 「나타내는 수량이 가장 적다」예요."]},{"stem":"막대그래프를 보고 운동회 종목을 정한 말 가운데 까닭이 알맞은 것은 어느 것인가요?","options":[{"t":"가장 많은 학생이 좋아하므로 여럿이 즐길 수 있다","correct":true},{"t":"막대 색이 가장 예쁘다","mis":"M5-2-u6-X17"},{"t":"막대가 가장 왼쪽에 있다","mis":"M5-2-u6-X17"},{"t":"가장 적은 학생이 좋아한다","mis":"M5-2-u6-X18"}],"explanation":["막대그래프는 막대의 길이로 수량을 나타내요.","막대가 길수록 수량이 많고 짧을수록 적어요.","정답은 「가장 많은 학생이 좋아하므로 여럿이 즐길 수 있다」예요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#2','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',1,'mc','auto','평균을 바르게 설명한 것은 어느 것인가요?',ARRAY['M5-2-u6-X01','M5-2-u6-X02']::text[],true,'{"seq":2,"concept":"M5-2-u6-C1","difficulty":1,"kind":"mc","stem":"평균을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"각 자룟값을 고르게 하여 그 자료를 대표하는 값으로 정한 값","correct":true},{"t":"자룟값 가운데 가장 큰 값","mis":"M5-2-u6-X01"},{"t":"자룟값 가운데 가장 많이 나온 값","mis":"M5-2-u6-X02"},{"t":"가장 큰 값과 가장 작은 값의 차","mis":"M5-2-u6-X02"}],"explanation":["평균은 자룟값을 고르게 해 자료 전체를 대표하는 값이에요.","가장 큰 값·가장 많이 나온 값·합과는 달라요.","「고르게 한 값」을 고르면 돼요."],"variant_rule":{"alt":[{"stem":"여러 자룟값을 한 수로 말할 때 쓰는 평균은 어떤 값인가요?","options":[{"t":"많은 쪽에서 덜어 적은 쪽에 채워 고르게 한 값","correct":true},{"t":"가장 작은 값","mis":"M5-2-u6-X01"},{"t":"가장 자주 나온 값","mis":"M5-2-u6-X02"},{"t":"자룟값을 모두 더한 값","mis":"M5-2-u6-X05"}],"explanation":["평균은 자룟값을 고르게 해 자료 전체를 대표하는 값이에요.","가장 큰 값·가장 많이 나온 값·합과는 달라요.","「고르게 한 값」을 고르면 돼요."]},{"stem":"「평균」이라는 말을 알맞게 쓴 것은 어느 것인가요?","options":[{"t":"여섯 반의 학생 수를 고르게 하면 21명이니 한 반의 평균 학생 수는 21명이다","correct":true},{"t":"가장 많은 반이 23명이니 평균 학생 수는 23명이다","mis":"M5-2-u6-X01"},{"t":"21명인 반이 가장 많으니 평균은 21명이고 다른 방법은 필요 없다","mis":"M5-2-u6-X02"},{"t":"평균이 21명이니 모든 반이 21명이다","mis":"M5-2-u6-X03"}],"explanation":["평균은 자룟값을 고르게 해 자료 전체를 대표하는 값이에요.","가장 큰 값·가장 많이 나온 값·합과는 달라요.","「고르게 한 값」을 고르면 돼요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#3','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',1,'sa','auto','세 친구가 만난 날수를 막대그래프로 나타냈어요. 8월 24일, 9월 25일, 10월 27일, 11월 28일이에요. 가장 많이 만난 달의 날수는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u6-C1","difficulty":1,"kind":"sa","stem":"세 친구가 만난 날수를 막대그래프로 나타냈어요. 8월 24일, 9월 25일, 10월 27일, 11월 28일이에요. 가장 많이 만난 달의 날수는 며칠인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["막대가 길수록 날수가 많아요.","가장 긴 막대를 찾아요.","가장 많이 만난 달은 28일이에요."],"mis":"M5-2-u6-X07","variant_rule":{"alt":[{"stem":"세 친구가 만난 날수를 막대그래프로 나타냈어요. 3월 18일, 4월 21일, 5월 20일, 6월 23일이에요. 가장 많이 만난 달의 날수는 며칠인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["막대가 길수록 날수가 많아요.","가장 긴 막대를 찾아요.","가장 많이 만난 달은 23일이에요."]},{"stem":"세 친구가 만난 날수를 막대그래프로 나타냈어요. 9월 22일, 10월 26일, 11월 25일, 12월 21일이에요. 가장 많이 만난 달의 날수는 며칠인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["막대가 길수록 날수가 많아요.","가장 긴 막대를 찾아요.","가장 많이 만난 달은 26일이에요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#4','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',1,'mc','auto','연정이 1분 동안의 심박수를 5번 잰 결과 평균이 82회였어요. 바르게 설명한 것은 어느 것인가요?',ARRAY['M5-2-u6-X03','M5-2-u6-X01']::text[],true,'{"seq":4,"concept":"M5-2-u6-C1","difficulty":1,"kind":"mc","stem":"연정이 1분 동안의 심박수를 5번 잰 결과 평균이 82회였어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"5번 잰 기록을 고르게 하면 82회이다","correct":true},{"t":"5번 잰 기록이 모두 82회이다","mis":"M5-2-u6-X03"},{"t":"가장 높은 기록이 82회이다","mis":"M5-2-u6-X01"},{"t":"82회보다 낮은 기록은 없다","mis":"M5-2-u6-X03"}],"explanation":["평균 82회는 기록들을 고르게 한 값이에요.","기록이 모두 82회라는 뜻도, 가장 높은 기록이라는 뜻도 아니에요.","82회보다 높은 기록과 낮은 기록이 섞여 있을 수 있어요."],"variant_rule":{"alt":[{"stem":"라온이 줄넘기 기록을 6번 잰 결과 평균이 92번이었어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"6번 잰 기록을 고르게 하면 92번이다","correct":true},{"t":"6번 잰 기록이 모두 92번이다","mis":"M5-2-u6-X03"},{"t":"가장 높은 기록이 92번이다","mis":"M5-2-u6-X01"},{"t":"92번보다 낮은 기록은 없다","mis":"M5-2-u6-X03"}],"explanation":["평균 92번은 기록들을 고르게 한 값이에요.","기록이 모두 92번이라는 뜻도, 가장 높은 기록이라는 뜻도 아니에요.","92번보다 높은 기록과 낮은 기록이 섞여 있을 수 있어요."]},{"stem":"하린이 하루 독서 시간을 4번 잰 결과 평균이 35분이었어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"4번 잰 기록을 고르게 하면 35분이다","correct":true},{"t":"4번 잰 기록이 모두 35분이다","mis":"M5-2-u6-X03"},{"t":"가장 높은 기록이 35분이다","mis":"M5-2-u6-X01"},{"t":"35분보다 낮은 기록은 없다","mis":"M5-2-u6-X03"}],"explanation":["평균 35분은 기록들을 고르게 한 값이에요.","기록이 모두 35분이라는 뜻도, 가장 높은 기록이라는 뜻도 아니에요.","35분보다 높은 기록과 낮은 기록이 섞여 있을 수 있어요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#5','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',2,'sa','auto','봉지 4개에 든 초코볼이 24개, 23개, 24개, 25개예요. 많은 봉지에서 덜어 적은 봉지에 채워 고르게 하면 한 봉지에 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u6-C1","difficulty":2,"kind":"sa","stem":"봉지 4개에 든 초코볼이 24개, 23개, 24개, 25개예요. 많은 봉지에서 덜어 적은 봉지에 채워 고르게 하면 한 봉지에 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["25개인 봉지에서 덜어 23개인 봉지에 채워 봐요.","덜어 낸 만큼 채우니 모두의 수는 그대로예요.","모두 24개가 되므로 고르게 한 값은 24개예요."],"mis":"M5-2-u6-X01","variant_rule":{"alt":[{"stem":"봉지 4개에 든 사탕이 13개, 15개, 14개, 14개예요. 많은 봉지에서 덜어 적은 봉지에 채워 고르게 하면 한 봉지에 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["15개인 봉지에서 덜어 13개인 봉지에 채워 봐요.","덜어 낸 만큼 채우니 모두의 수는 그대로예요.","모두 14개가 되므로 고르게 한 값은 14개예요."]},{"stem":"상자 5개에 든 구슬이 18개, 22개, 20개, 19개, 21개예요. 많은 상자에서 덜어 적은 상자에 채워 고르게 하면 한 상자에 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["22개인 상자에서 덜어 18개인 상자에 채워 봐요.","덜어 낸 만큼 채우니 모두의 수는 그대로예요.","모두 20개가 되므로 고르게 한 값은 20개예요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#6','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',2,'sa','auto','반별 학생 수를 고르게 하면 21명이에요. 19명인 4반에는 몇 명 채워야 21명이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u6-C1","difficulty":2,"kind":"sa","stem":"반별 학생 수를 고르게 하면 21명이에요. 19명인 4반에는 몇 명 채워야 21명이 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["19명에서 21명이 되려면 모자란 만큼 채워요.","21 − 19 = 2예요.","그래서 2명 채워야 해요."],"mis":"M5-2-u6-X04","variant_rule":{"alt":[{"stem":"반별 학생 수를 고르게 하면 21명이에요. 23명인 1반에서는 몇 명 덜어 내야 21명이 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["23명에서 21명이 되려면 넘치는 만큼 덜어 내요.","23 − 21 = 2예요.","그래서 2명 덜어 내야 해요."]},{"stem":"봉지마다 든 초코볼 수를 고르게 하면 24개예요. 23개인 셋째 봉지에는 몇 개 채워야 24개가 되나요? 숫자로 쓰세요.","answer":["1"],"explanation":["23개에서 24개가 되려면 모자란 만큼 채워요.","24 − 23 = 1이에요.","그래서 1개 채워야 해요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#7','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',2,'sa','auto','세 친구가 만난 날수를 막대그래프로 나타냈어요. 8월 24일, 9월 25일, 10월 27일, 11월 28일이에요. 가장 많이 만난 달과 가장 적게 만난 달의 날수 차는 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u6-C1","difficulty":2,"kind":"sa","stem":"세 친구가 만난 날수를 막대그래프로 나타냈어요. 8월 24일, 9월 25일, 10월 27일, 11월 28일이에요. 가장 많이 만난 달과 가장 적게 만난 달의 날수 차는 며칠인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가장 긴 막대는 28일, 가장 짧은 막대는 24일이에요.","차는 큰 수에서 작은 수를 빼요.","28 − 24 = 4(일)이에요."],"mis":"M5-2-u6-X07","variant_rule":{"alt":[{"stem":"세 친구가 만난 날수를 막대그래프로 나타냈어요. 3월 18일, 4월 21일, 5월 20일, 6월 23일이에요. 가장 많이 만난 달과 가장 적게 만난 달의 날수 차는 며칠인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["가장 긴 막대는 23일, 가장 짧은 막대는 18일이에요.","차는 큰 수에서 작은 수를 빼요.","23 − 18 = 5(일)이에요."]},{"stem":"세 친구가 만난 날수를 막대그래프로 나타냈어요. 9월 22일, 10월 26일, 11월 25일, 12월 21일이에요. 가장 많이 만난 달과 가장 적게 만난 달의 날수 차는 며칠인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["가장 긴 막대는 26일, 가장 짧은 막대는 21일이에요.","차는 큰 수에서 작은 수를 빼요.","26 − 21 = 5(일)이에요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#8','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',2,'ox','auto','많은 쪽에서 덜어 적은 쪽에 채워 고르게 해도 자룟값을 모두 더한 값은 그대로예요.',ARRAY['M5-2-u6-X04']::text[],true,'{"seq":8,"concept":"M5-2-u6-C1","difficulty":2,"kind":"ox","stem":"많은 쪽에서 덜어 적은 쪽에 채워 고르게 해도 자룟값을 모두 더한 값은 그대로예요.","answer":"O","reason_options":[{"t":"덜어 낸 만큼 채웠으므로","correct":true},{"t":"옮기는 동안 조금씩 줄어들므로","mis":"M5-2-u6-X04"}],"mis":"M5-2-u6-X04","explanation":["고르게 하기는 옮기기만 하는 일이에요.","덜어 낸 만큼 채우니 합은 그대로예요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"어느 반의 평균 키가 145 cm이면 그 반 학생은 모두 키가 145 cm예요.","answer":"X","reason_options":[{"t":"평균은 키를 고르게 한 값일 뿐이므로","correct":true},{"t":"평균은 모두의 값과 같으므로","mis":"M5-2-u6-X03"}],"explanation":["평균은 자료를 고르게 한 값이에요.","145 cm보다 큰 학생도, 작은 학생도 있을 수 있어요.","그래서 틀린 말이에요."]},{"stem":"평균은 자룟값 가운데 가장 큰 값으로 정해요.","answer":"X","reason_options":[{"t":"평균은 자룟값을 고르게 한 값이므로","correct":true},{"t":"가장 큰 값이 자료를 가장 잘 대표하므로","mis":"M5-2-u6-X01"}],"explanation":["가장 큰 값은 한 자료일 뿐이에요.","평균은 모든 자룟값을 고르게 한 값이에요.","그래서 틀린 말이에요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#9','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',2,'sa','auto','태오가 5일 동안 마신 우유는 300 mL, 200 mL, 300 mL, 400 mL, 300 mL예요. 많은 날에서 덜어 적은 날에 채워 고르게 한 뒤, 5일 동안의 값을 모두 더하면 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u6-C1","difficulty":2,"kind":"sa","stem":"태오가 5일 동안 마신 우유는 300 mL, 200 mL, 300 mL, 400 mL, 300 mL예요. 많은 날에서 덜어 적은 날에 채워 고르게 한 뒤, 5일 동안의 값을 모두 더하면 몇 mL인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["덜어 낸 만큼 채웠으니 전체 양은 바뀌지 않아요.","옮기기 전 합은 300 + 200 + 300 + 400 + 300 = 1500이에요.","고르게 한 뒤에도 300 × 5 = 1500 그대로예요."],"mis":"M5-2-u6-X04","variant_rule":{"alt":[{"stem":"하린이 4일 동안 마신 물은 250 mL, 300 mL, 200 mL, 350 mL예요. 많은 날에서 덜어 적은 날에 채워 고르게 한 뒤, 4일 동안의 값을 모두 더하면 몇 mL인가요? 숫자로 쓰세요.","answer":["1100"],"explanation":["덜어 낸 만큼 채웠으니 전체 양은 바뀌지 않아요.","옮기기 전 합은 250 + 300 + 200 + 350 = 1100이에요.","고르게 한 뒤에도 275 × 4 = 1100 그대로예요."]},{"stem":"도윤이 5일 동안 마신 우유는 400 mL, 350 mL, 300 mL, 350 mL, 350 mL예요. 많은 날에서 덜어 적은 날에 채워 고르게 한 뒤, 5일 동안의 값을 모두 더하면 몇 mL인가요? 숫자로 쓰세요.","answer":["1750"],"explanation":["덜어 낸 만큼 채웠으니 전체 양은 바뀌지 않아요.","옮기기 전 합은 400 + 350 + 300 + 350 + 350 = 1750이에요.","고르게 한 뒤에도 350 × 5 = 1750 그대로예요."]}]}}'::jsonb),
('g5_2_math_u6_L02_basic#10','math',5,2,'u6','L02','g5_2_math_u6_L02_basic','lesson_basic','M5-2-u6-C1',3,'mc','auto','많은 쪽에서 덜어 적은 쪽에 채워 고르게 한 값이 자료를 대표할 수 있는 까닭은 무엇인가요?',ARRAY['M5-2-u6-X01','M5-2-u6-X06','M5-2-u6-X04']::text[],true,'{"seq":10,"concept":"M5-2-u6-C1","difficulty":3,"kind":"mc","stem":"많은 쪽에서 덜어 적은 쪽에 채워 고르게 한 값이 자료를 대표할 수 있는 까닭은 무엇인가요?","options":[{"t":"덜어 낸 만큼 채워 전체 양은 그대로이기 때문이다","correct":true},{"t":"가장 큰 값만 남기기 때문이다","mis":"M5-2-u6-X01"},{"t":"자룟값의 수가 줄어들기 때문이다","mis":"M5-2-u6-X06"},{"t":"옮긴 뒤에는 전체 양이 늘어나기 때문이다","mis":"M5-2-u6-X04"}],"explanation":["고르게 할 때는 많은 쪽에서 덜어 적은 쪽에 그만큼 채워요.","그래서 전체 양(합)은 그대로예요.","전체를 그대로 두고 같게 만든 값이라 자료를 대표해요."],"variant_rule":{"alt":[{"stem":"우유 양을 고르게 할 때 지켜야 할 것은 무엇인가요?","options":[{"t":"덜어 낸 양만큼만 다른 날에 채운다","correct":true},{"t":"많은 날의 우유를 모두 버린다","mis":"M5-2-u6-X04"},{"t":"가장 많이 마신 날로 모두 맞춘다","mis":"M5-2-u6-X01"},{"t":"적은 날에 더 많이 채워 넣는다","mis":"M5-2-u6-X04"}],"explanation":["고르게 할 때는 많은 쪽에서 덜어 적은 쪽에 그만큼 채워요.","그래서 전체 양(합)은 그대로예요.","전체를 그대로 두고 같게 만든 값이라 자료를 대표해요."]},{"stem":"고르게 하기 전과 뒤를 견주었어요. 바뀌지 않는 것은 무엇인가요?","options":[{"t":"모든 자룟값의 합","correct":true},{"t":"가장 큰 자룟값","mis":"M5-2-u6-X01"},{"t":"가장 작은 자룟값","mis":"M5-2-u6-X01"},{"t":"자룟값이 서로 다른 정도","mis":"M5-2-u6-X02"}],"explanation":["고르게 할 때는 많은 쪽에서 덜어 적은 쪽에 그만큼 채워요.","그래서 전체 양(합)은 그대로예요.","전체를 그대로 두고 같게 만든 값이라 자료를 대표해요."]}]}}'::jsonb),
