('g5_2_math_u6_L05_challenge#7','math',5,2,'u6','L05','g5_2_math_u6_L05_challenge','lesson_challenge','M5-2-u6-C5',3,'ox','auto','나올 수 있는 경우가 두 가지이면 가능성은 언제나 반반이에요.',ARRAY['M5-2-u6-X13']::text[],true,'{"seq":7,"concept":"M5-2-u6-C5","difficulty":3,"kind":"ox","stem":"나올 수 있는 경우가 두 가지이면 가능성은 언제나 반반이에요.","answer":"X","reason_options":[{"t":"두 경우가 차지한 칸이나 개수가 같아야 반반이므로","correct":true},{"t":"경우가 두 가지면 늘 똑같이 나오므로","mis":"M5-2-u6-X13"}],"mis":"M5-2-u6-X13","explanation":["보라색 3칸·연두색 1칸 회전판도 색은 두 가지예요.","그래도 연두색에 멈출 가능성은 반반보다 작아요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"연두색 칸이 많은 회전판일수록 화살이 연두색에 멈출 가능성이 작아요.","answer":"X","reason_options":[{"t":"연두색 칸이 많을수록 그 칸에 멈출 가능성이 크므로","correct":true},{"t":"칸이 많으면 화살이 피해 가므로","mis":"M5-2-u6-X12"}],"explanation":["칸이 많을수록 화살이 그 칸에 멈추기 쉬워요.","연두색이 많으면 연두색에 멈출 가능성이 커요.","그래서 틀린 말이에요."]},{"stem":"빨간 공만 든 상자에서 파란 공을 꺼내는 것은 불가능해요.","answer":"O","reason_options":[{"t":"상자에 파란 공이 하나도 없으므로","correct":true},{"t":"공은 언제나 반반으로 나오므로","mis":"M5-2-u6-X12"}],"explanation":["상자에는 빨간 공만 있어요.","없는 공은 꺼낼 수 없어요.","그래서 맞는 말이에요."]}]}}'::jsonb),
