('g5_2_math_u6_L08_challenge#8','math',5,2,'u6','L08','g5_2_math_u6_L08_challenge','lesson_challenge','M5-2-u6-C8',4,'sa','auto','표를 보고 일주일 전체의 하루 산불 횟수 평균을 반올림하여 일의 자리까지 나타내면 약 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u6-C8","difficulty":4,"kind":"sa","stem":"표를 보고 일주일 전체의 하루 산불 횟수 평균을 반올림하여 일의 자리까지 나타내면 약 몇 회인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["월요일부터 일요일까지 7일을 모두 더하면 270이에요.","270 ÷ 7을 계산하면 38.5…예요.","반올림하여 약 39예요."],"mis":"M5-2-u6-X06","asset":{"type":"passage","title":"요일별 산불 횟수(회)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","회 | 37 | 35 | 28 | 36 | 39 | 41 | 54"],"numbered":false},"variant_rule":{"alt":[{"stem":"표를 보고 일주일 전체의 하루 놀이터에 온 어린이 수 평균을 반올림하여 일의 자리까지 나타내면 약 몇 명인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["월요일부터 일요일까지 7일을 모두 더하면 333이에요.","333 ÷ 7을 계산하면 47.5…예요.","반올림하여 약 48이에요."],"asset":{"type":"passage","title":"요일별 놀이터에 온 어린이 수(명)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","명 | 42 | 38 | 45 | 40 | 35 | 63 | 70"],"numbered":false}},{"stem":"표를 보고 일주일 전체의 하루 공원 쓰레기 봉투 수 평균을 반올림하여 일의 자리까지 나타내면 약 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["월요일부터 일요일까지 7일을 모두 더하면 120이에요.","120 ÷ 7을 계산하면 17.1…예요.","반올림하여 약 17이에요."],"asset":{"type":"passage","title":"요일별 공원 쓰레기 봉투 수(개)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","개 | 12 | 15 | 11 | 14 | 13 | 24 | 31"],"numbered":false}}]}}'::jsonb),
('g5_2_math_u6_L08_challenge#9','math',5,2,'u6','L08','g5_2_math_u6_L08_challenge','lesson_challenge','M5-2-u6-C8',4,'sa','auto','표를 보고 2022년부터 2024년까지 한 해 산불 횟수 평균(반올림하여 일의 자리)과 2024년 합계의 차를 구하면 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u6-C8","difficulty":4,"kind":"sa","stem":"표를 보고 2022년부터 2024년까지 한 해 산불 횟수 평균(반올림하여 일의 자리)과 2024년 합계의 차를 구하면 몇 회인가요? 숫자로 쓰세요.","answer":["265"],"explanation":["한 해 평균은 (756 + 596 + 279) ÷ 3, 반올림하면 약 544예요.","2024년 합계는 279예요.","차는 265예요."],"mis":"M5-2-u6-X17","asset":{"type":"passage","title":"2022~2024년 계절별 산불 횟수(회)","lines":["연도 | 봄 | 여름 | 가을 | 겨울 | 합계","2022년 | 377 | 29 | 61 | 289 | 756","2023년 | 370 | 12 | 48 | 166 | 596","2024년 | 158 | 35 | 26 | 60 | 279"],"numbered":false},"variant_rule":{"alt":[{"stem":"표를 보고 2022년부터 2024년까지 한 해 미세먼지 나쁨 날수 평균(반올림하여 일의 자리)과 2023년 합계의 차를 구하면 며칠인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 해 평균은 (66 + 56 + 58) ÷ 3, 반올림하면 약 60이에요.","2023년 합계는 56이에요.","차는 4예요."],"asset":{"type":"passage","title":"2022~2024년 계절별 미세먼지 나쁨 날수(일)","lines":["연도 | 봄 | 여름 | 가을 | 겨울 | 합계","2022년 | 31 | 2 | 9 | 24 | 66","2023년 | 27 | 1 | 8 | 20 | 56","2024년 | 23 | 3 | 10 | 22 | 58"],"numbered":false}},{"stem":"표를 보고 2022년부터 2024년까지 한 해 비 온 날수 평균(반올림하여 일의 자리)과 2023년 합계의 차를 구하면 며칠인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["한 해 평균은 (92 + 90 + 92) ÷ 3, 반올림하면 약 91이에요.","2023년 합계는 90이에요.","차는 1이에요."],"asset":{"type":"passage","title":"2022~2024년 계절별 비 온 날수(일)","lines":["연도 | 봄 | 여름 | 가을 | 겨울 | 합계","2022년 | 21 | 44 | 18 | 9 | 92","2023년 | 16 | 39 | 22 | 13 | 90","2024년 | 20 | 47 | 17 | 8 | 92"],"numbered":false}}]}}'::jsonb),
('g5_2_math_u6_L08_challenge#10','math',5,2,'u6','L08','g5_2_math_u6_L08_challenge','lesson_challenge','M5-2-u6-C8',4,'essay','teacher','요일별 산불 횟수는 월 37회, 화 35회, 수 28회, 목 36회, 금 39회, 토 41회, 일 54회예요. 평일과 주말 중 언제 산불이 더 많이 생긴다고 볼 수 있는지 평균을 구해 쓰고, 합으로 견주면 안 되는 까닭도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u6-C8","difficulty":4,"kind":"essay","stem":"요일별 산불 횟수는 월 37회, 화 35회, 수 28회, 목 36회, 금 39회, 토 41회, 일 54회예요. 평일과 주말 중 언제 산불이 더 많이 생긴다고 볼 수 있는지 평균을 구해 쓰고, 합으로 견주면 안 되는 까닭도 쓰세요.","answer_guide":{"answer":"예: 평일 합은 175회이므로 평균은 175 ÷ 5 = 35(회)이다. 주말 합은 95회이므로 평균은 95 ÷ 2 = 47.5, 반올림하면 약 48회이다. 하루당 평균은 주말이 더 크므로 산불은 주말에 더 많이 생긴다고 볼 수 있다. 평일은 5일, 주말은 2일로 날수가 달라 합으로 견주면 날수가 많은 평일이 커 보이므로 평균으로 견주어야 한다.","scoring_points":["평일 평균 35회를 구했는가","주말 평균 약 48회를 구해 주말이 더 많다고 썼는가","날수가 달라 합이 아니라 평균으로 견준다고 썼는가"]},"explanation":["평일 175 ÷ 5 = 35(회)이에요.","주말 95 ÷ 2 = 47.5, 약 48회예요.","날수가 달라 평균으로 견줘요 — 주말이 더 많아요."]}'::jsonb),
('g5_2_math_u6_review_a#1','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C1',1,'mc','auto','연정이 1분 동안의 심박수를 5번 잰 결과 평균이 82회였어요. 바르게 설명한 것은 어느 것인가요?',ARRAY['M5-2-u6-X03','M5-2-u6-X01']::text[],true,'{"seq":1,"concept":"M5-2-u6-C1","difficulty":1,"kind":"mc","stem":"연정이 1분 동안의 심박수를 5번 잰 결과 평균이 82회였어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"5번 잰 기록을 고르게 하면 82회이다","correct":true},{"t":"5번 잰 기록이 모두 82회이다","mis":"M5-2-u6-X03"},{"t":"가장 높은 기록이 82회이다","mis":"M5-2-u6-X01"},{"t":"82회보다 낮은 기록은 없다","mis":"M5-2-u6-X03"}],"explanation":["평균 82회는 기록들을 고르게 한 값이에요.","기록이 모두 82회라는 뜻도, 가장 높은 기록이라는 뜻도 아니에요.","82회보다 높은 기록과 낮은 기록이 섞여 있을 수 있어요."],"variant_rule":{"alt":[{"stem":"라온이 줄넘기 기록을 6번 잰 결과 평균이 92번이었어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"6번 잰 기록을 고르게 하면 92번이다","correct":true},{"t":"6번 잰 기록이 모두 92번이다","mis":"M5-2-u6-X03"},{"t":"가장 높은 기록이 92번이다","mis":"M5-2-u6-X01"},{"t":"92번보다 낮은 기록은 없다","mis":"M5-2-u6-X03"}],"explanation":["평균 92번은 기록들을 고르게 한 값이에요.","기록이 모두 92번이라는 뜻도, 가장 높은 기록이라는 뜻도 아니에요.","92번보다 높은 기록과 낮은 기록이 섞여 있을 수 있어요."]},{"stem":"하린이 하루 독서 시간을 4번 잰 결과 평균이 35분이었어요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"4번 잰 기록을 고르게 하면 35분이다","correct":true},{"t":"4번 잰 기록이 모두 35분이다","mis":"M5-2-u6-X03"},{"t":"가장 높은 기록이 35분이다","mis":"M5-2-u6-X01"},{"t":"35분보다 낮은 기록은 없다","mis":"M5-2-u6-X03"}],"explanation":["평균 35분은 기록들을 고르게 한 값이에요.","기록이 모두 35분이라는 뜻도, 가장 높은 기록이라는 뜻도 아니에요.","35분보다 높은 기록과 낮은 기록이 섞여 있을 수 있어요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#2','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C2',1,'sa','auto','반별 안경 쓴 학생 수는 1반 4명, 2반 2명, 3반 6명, 4반 4명이에요. 자룟값의 합은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u6-C2","difficulty":1,"kind":"sa","stem":"반별 안경 쓴 학생 수는 1반 4명, 2반 2명, 3반 6명, 4반 4명이에요. 자룟값의 합은 몇 명인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["합은 자룟값을 모두 더한 값이에요.","4 + 2 + 6 + 4 = 16이에요.","그래서 합은 16명이에요."],"mis":"M5-2-u6-X07","variant_rule":{"alt":[{"stem":"연도별로 12월에 눈이 온 날수는 2021년 6일, 2022년 3일, 2023년 5일, 2024년 6일이에요. 자룟값의 합은 며칠인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["합은 자룟값을 모두 더한 값이에요.","6 + 3 + 5 + 6 = 20이에요.","그래서 합은 20일이에요."]},{"stem":"수호가 지난주 요일별로 손을 씻은 횟수는 월 7회, 화 8회, 수 6회, 목 7회, 금 6회, 토 8회, 일 7회예요. 자룟값의 합은 몇 회인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["합은 자룟값을 모두 더한 값이에요.","7 + 8 + 6 + 7 + 6 + 8 + 7 = 49예요.","그래서 합은 49회예요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#3','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C5',1,'mc','auto','끓는 물에 넣은 얼음이 녹을 가능성을 말로 나타내면 어느 것인가요?',ARRAY['M5-2-u6-X12']::text[],true,'{"seq":3,"concept":"M5-2-u6-C5","difficulty":1,"kind":"mc","stem":"끓는 물에 넣은 얼음이 녹을 가능성을 말로 나타내면 어느 것인가요?","options":[{"t":"확실하다","correct":true},{"t":"불가능하다","mis":"M5-2-u6-X12"},{"t":"~일 것 같다","mis":"M5-2-u6-X12"},{"t":"반반이다","mis":"M5-2-u6-X12"}],"explanation":["가능성은 불가능하다 · ~아닐 것 같다 · 반반이다 · ~일 것 같다 · 확실하다로 나타내요.","끓는 물에 넣은 얼음이 녹을 가능성을 따져 봐요.","알맞은 말은 「확실하다」예요."],"variant_rule":{"alt":[{"stem":"빨간 공만 2개 들어 있는 상자에서 공을 한 개 꺼낼 때 파란 공이 나올 가능성을 말로 나타내면 어느 것인가요?","options":[{"t":"불가능하다","correct":true},{"t":"확실하다","mis":"M5-2-u6-X12"},{"t":"~아닐 것 같다","mis":"M5-2-u6-X12"},{"t":"반반이다","mis":"M5-2-u6-X12"}],"explanation":["가능성은 불가능하다 · ~아닐 것 같다 · 반반이다 · ~일 것 같다 · 확실하다로 나타내요.","빨간 공만 2개 들어 있는 상자에서 공을 한 개 꺼낼 때 파란 공이 나올 가능성을 따져 봐요.","알맞은 말은 「불가능하다」예요."]},{"stem":"동전을 던질 때 그림면이 나올 가능성을 말로 나타내면 어느 것인가요?","options":[{"t":"반반이다","correct":true},{"t":"확실하다","mis":"M5-2-u6-X12"},{"t":"불가능하다","mis":"M5-2-u6-X12"},{"t":"~일 것 같다","mis":"M5-2-u6-X12"}],"explanation":["가능성은 불가능하다 · ~아닐 것 같다 · 반반이다 · ~일 것 같다 · 확실하다로 나타내요.","동전을 던질 때 그림면이 나올 가능성을 따져 봐요.","알맞은 말은 「반반이다」예요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#4','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C6',1,'mc','auto','계산기로 1 + 2를 계산했을 때 3이 나올 가능성을 수로 나타내면 어느 것인가요?',ARRAY['M5-2-u6-X14','M5-2-u6-X12']::text[],true,'{"seq":4,"concept":"M5-2-u6-C6","difficulty":1,"kind":"mc","stem":"계산기로 1 + 2를 계산했을 때 3이 나올 가능성을 수로 나타내면 어느 것인가요?","options":[{"t":"1","correct":true},{"t":"⟨1/2⟩","mis":"M5-2-u6-X14"},{"t":"0","mis":"M5-2-u6-X12"},{"t":"2","mis":"M5-2-u6-X14"}],"explanation":["불가능하다는 0, 반반이다는 ⟨1/2⟩, 확실하다는 1이에요.","이 일의 가능성은 「확실하다」예요.","그래서 1이에요."],"variant_rule":{"alt":[{"stem":"주사위를 굴려 나온 눈의 수가 7이 될 가능성을 수로 나타내면 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M5-2-u6-X14"},{"t":"⟨1/2⟩","mis":"M5-2-u6-X14"},{"t":"2","mis":"M5-2-u6-X14"}],"explanation":["불가능하다는 0, 반반이다는 ⟨1/2⟩, 확실하다는 1이에요.","이 일의 가능성은 「불가능하다」예요.","그래서 0이에요."]},{"stem":"주사위를 굴려 홀수가 나올 가능성을 수로 나타내면 어느 것인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"1","mis":"M5-2-u6-X14"},{"t":"2","mis":"M5-2-u6-X14"},{"t":"0","mis":"M5-2-u6-X12"}],"explanation":["불가능하다는 0, 반반이다는 ⟨1/2⟩, 확실하다는 1이에요.","이 일의 가능성은 「반반이다」예요.","그래서 ⟨1/2⟩이에요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#5','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C7',1,'sa','auto','보라색 카드를 뽑을 가능성이 반반인 카드 더미에 카드가 모두 6장 있어요. 보라색 카드는 몇 장일 것 같나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u6-C7","difficulty":1,"kind":"sa","stem":"보라색 카드를 뽑을 가능성이 반반인 카드 더미에 카드가 모두 6장 있어요. 보라색 카드는 몇 장일 것 같나요? 숫자로 쓰세요.","answer":["3"],"explanation":["반반은 전체의 절반이라는 뜻이에요.","6장의 절반을 구해요.","6 ÷ 2 = 3(장)이에요."],"mis":"M5-2-u6-X14","variant_rule":{"alt":[{"stem":"노란색 카드를 뽑을 가능성이 반반인 카드 더미에 카드가 모두 10장 있어요. 노란색 카드는 몇 장일 것 같나요? 숫자로 쓰세요.","answer":["5"],"explanation":["반반은 전체의 절반이라는 뜻이에요.","10장의 절반을 구해요.","10 ÷ 2 = 5(장)이에요."]},{"stem":"빨간색 카드를 뽑을 가능성이 반반인 카드 더미에 카드가 모두 8장 있어요. 빨간색 카드는 몇 장일 것 같나요? 숫자로 쓰세요.","answer":["4"],"explanation":["반반은 전체의 절반이라는 뜻이에요.","8장의 절반을 구해요.","8 ÷ 2 = 4(장)이에요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#6','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C8',1,'sa','auto','표를 보고 평일(월~금) 산불 횟수의 평균을 구하면 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u6-C8","difficulty":1,"kind":"sa","stem":"표를 보고 평일(월~금) 산불 횟수의 평균을 구하면 몇 회인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["평일은 월·화·수·목·금 5일이에요.","37 + 35 + 28 + 36 + 39 = 175예요.","175 ÷ 5 = 35예요."],"mis":"M5-2-u6-X06","asset":{"type":"passage","title":"요일별 산불 횟수(회)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","회 | 37 | 35 | 28 | 36 | 39 | 41 | 54"],"numbered":false},"variant_rule":{"alt":[{"stem":"표를 보고 평일(월~금) 놀이터에 온 어린이 수의 평균을 구하면 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["평일은 월·화·수·목·금 5일이에요.","42 + 38 + 45 + 40 + 35 = 200이에요.","200 ÷ 5 = 40이에요."],"asset":{"type":"passage","title":"요일별 놀이터에 온 어린이 수(명)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","명 | 42 | 38 | 45 | 40 | 35 | 63 | 70"],"numbered":false}},{"stem":"표를 보고 평일(월~금) 공원 쓰레기 봉투 수의 평균을 구하면 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["평일은 월·화·수·목·금 5일이에요.","12 + 15 + 11 + 14 + 13 = 65예요.","65 ÷ 5 = 13이에요."],"asset":{"type":"passage","title":"요일별 공원 쓰레기 봉투 수(개)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","개 | 12 | 15 | 11 | 14 | 13 | 24 | 31"],"numbered":false}}]}}'::jsonb),
('g5_2_math_u6_review_a#7','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C2',1,'sa','auto','지우의 제기차기 기록 5개, 2개, 7개, 10개를 종이띠로 이어 붙였어요. 이 띠를 4등분이 되게 똑같이 접으면 한 칸은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u6-C2","difficulty":1,"kind":"sa","stem":"지우의 제기차기 기록 5개, 2개, 7개, 10개를 종이띠로 이어 붙였어요. 이 띠를 4등분이 되게 똑같이 접으면 한 칸은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["이어 붙인 띠는 5 + 2 + 7 + 10 = 24(개)이에요.","4등분으로 접는 것은 4로 나누는 것과 같아요.","24 ÷ 4 = 6 — 한 칸이 평균이에요."],"mis":"M5-2-u6-X05","variant_rule":{"alt":[{"stem":"민준의 제기차기 기록 3개, 8개, 6개, 7개를 종이띠로 이어 붙였어요. 이 띠를 4등분이 되게 똑같이 접으면 한 칸은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["이어 붙인 띠는 3 + 8 + 6 + 7 = 24(개)이에요.","4등분으로 접는 것은 4로 나누는 것과 같아요.","24 ÷ 4 = 6 — 한 칸이 평균이에요."]},{"stem":"서연의 제기차기 기록 4개, 9개, 5개를 종이띠로 이어 붙였어요. 이 띠를 3등분이 되게 똑같이 접으면 한 칸은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["이어 붙인 띠는 4 + 9 + 5 = 18(개)이에요.","3등분으로 접는 것은 3으로 나누는 것과 같아요.","18 ÷ 3 = 6 — 한 칸이 평균이에요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#8','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C4',1,'sa','auto','우리 모둠 친구들에게 한 달 동안 학교 체육 수업 이외에 운동하는 횟수를 물어 자료를 모았어요. 준희 12회, 아현 16회, 지호 15회, 하람 13회예요. 우리 모둠의 평균은 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u6-C4","difficulty":1,"kind":"sa","stem":"우리 모둠 친구들에게 한 달 동안 학교 체육 수업 이외에 운동하는 횟수를 물어 자료를 모았어요. 준희 12회, 아현 16회, 지호 15회, 하람 13회예요. 우리 모둠의 평균은 몇 회인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["모은 자료의 합은 12 + 16 + 15 + 13 = 56이에요.","모둠 친구는 4명이에요.","56 ÷ 4 = 14예요."],"mis":"M5-2-u6-X05","variant_rule":{"alt":[{"stem":"우리 모둠 친구들에게 일주일 동안 집이 아닌 곳에서 식사한 횟수를 물어 자료를 모았어요. 지영 7회, 동희 8회, 수지 8회, 하민 5회예요. 우리 모둠의 평균은 몇 회인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["모은 자료의 합은 7 + 8 + 8 + 5 = 28이에요.","모둠 친구는 4명이에요.","28 ÷ 4 = 7이에요."]},{"stem":"우리 모둠 친구들에게 한 달 동안 읽은 책의 권수를 물어 자료를 모았어요. 수아 3권, 도윤 5권, 하린 4권, 민준 2권, 서연 6권이에요. 우리 모둠의 평균은 몇 권인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["모은 자료의 합은 3 + 5 + 4 + 2 + 6 = 20이에요.","모둠 친구는 5명이에요.","20 ÷ 5 = 4예요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#9','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C2',2,'sa','auto','세호네 모둠 5명이 건 고리 수는 세호 9개, 민아 7개, 태윤 10개, 소라 7개, 진우 7개예요. 이 자료의 평균은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u6-C2","difficulty":2,"kind":"sa","stem":"세호네 모둠 5명이 건 고리 수는 세호 9개, 민아 7개, 태윤 10개, 소라 7개, 진우 7개예요. 이 자료의 평균은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["합은 9 + 7 + 10 + 7 + 7 = 40이에요.","자료는 사람마다 하나씩 5개예요.","평균은 40 ÷ 5 = 8이에요."],"mis":"M5-2-u6-X05","variant_rule":{"alt":[{"stem":"연수네 모둠이 투호에 넣은 화살 수는 연수 4개, 라희 4개, 지안 6개, 도하 4개, 윤서 7개예요. 이 자료의 평균은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["합은 4 + 4 + 6 + 4 + 7 = 25예요.","자료는 사람마다 하나씩 5개예요.","평균은 25 ÷ 5 = 5예요."]},{"stem":"반별 안경 쓴 학생 수는 1반 4명, 2반 2명, 3반 6명, 4반 4명이에요. 이 자료의 평균은 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["합은 4 + 2 + 6 + 4 = 16이에요.","자료는 반마다 하나씩 4개예요.","평균은 16 ÷ 4 = 4예요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#10','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C1',2,'sa','auto','반별 학생 수를 고르게 하면 21명이에요. 19명인 4반에는 몇 명 채워야 21명이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u6-C1","difficulty":2,"kind":"sa","stem":"반별 학생 수를 고르게 하면 21명이에요. 19명인 4반에는 몇 명 채워야 21명이 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["19명에서 21명이 되려면 모자란 만큼 채워요.","21 − 19 = 2예요.","그래서 2명 채워야 해요."],"mis":"M5-2-u6-X04","variant_rule":{"alt":[{"stem":"반별 학생 수를 고르게 하면 21명이에요. 23명인 1반에서는 몇 명 덜어 내야 21명이 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["23명에서 21명이 되려면 넘치는 만큼 덜어 내요.","23 − 21 = 2예요.","그래서 2명 덜어 내야 해요."]},{"stem":"봉지마다 든 초코볼 수를 고르게 하면 24개예요. 23개인 셋째 봉지에는 몇 개 채워야 24개가 되나요? 숫자로 쓰세요.","answer":["1"],"explanation":["23개에서 24개가 되려면 모자란 만큼 채워요.","24 − 23 = 1이에요.","그래서 1개 채워야 해요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#11','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C3',2,'sa','auto','수호네 집의 음식물 쓰레기 배출량은 5일 동안의 평균이 263 g이에요. 5일 동안의 양은 모두 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M5-2-u6-C3","difficulty":2,"kind":"sa","stem":"수호네 집의 음식물 쓰레기 배출량은 5일 동안의 평균이 263 g이에요. 5일 동안의 양은 모두 몇 g인가요? 숫자로 쓰세요.","answer":["1315"],"explanation":["평균은 합을 자료 수로 나눈 값이에요.","거꾸로 평균에 자료 수를 곱하면 합이 돼요.","263 × 5 = 1315예요."],"mis":"M5-2-u6-X09","variant_rule":{"alt":[{"stem":"하린이가 읽은 책의 쪽수는 7일 동안의 평균이 30쪽이에요. 7일 동안의 양은 모두 몇 쪽인가요? 숫자로 쓰세요.","answer":["210"],"explanation":["평균은 합을 자료 수로 나눈 값이에요.","거꾸로 평균에 자료 수를 곱하면 합이 돼요.","30 × 7 = 210이에요."]},{"stem":"태오가 마신 우유의 양은 5일 동안의 평균이 300 mL예요. 5일 동안의 양은 모두 몇 mL인가요? 숫자로 쓰세요.","answer":["1500"],"explanation":["평균은 합을 자료 수로 나눈 값이에요.","거꾸로 평균에 자료 수를 곱하면 합이 돼요.","300 × 5 = 1500이에요."]}]}}'::jsonb),
('g5_2_math_u6_review_a#12','math',5,2,'u6','','g5_2_math_u6_review_a','unit_review','M5-2-u6-C5',2,'mc','auto','똑같이 4칸으로 나눈 회전판이에요. 셋째 회전판에서 화살이 색칠한 칸에 멈출 가능성을 말로 나타내면 어느 것인가요?',ARRAY['M5-2-u6-X12']::text[],true,'{"seq":12,"concept":"M5-2-u6-C5","difficulty":2,"kind":"mc","stem":"똑같이 4칸으로 나눈 회전판이에요. 셋째 회전판에서 화살이 색칠한 칸에 멈출 가능성을 말로 나타내면 어느 것인가요?","options":[{"t":"확실하다","correct":true},{"t":"불가능하다","mis":"M5-2-u6-X12"},{"t":"~일 것 같다","mis":"M5-2-u6-X12"},{"t":"반반이다","mis":"M5-2-u6-X12"}],"explanation":["셋째 회전판은 4칸 가운데 4칸이 색칠되어 있어요.","색칠한 칸이 없으면 불가능, 절반이면 반반, 모두면 확실이에요.","그래서 「확실하다」예요."],"asset":{"type":"spin","n":4,"boards":[[],[0,1],[0,1,2,3],[0]]},"variant_rule":{"alt":[{"stem":"똑같이 4칸으로 나눈 회전판이에요. 첫째 회전판에서 화살이 색칠한 칸에 멈출 가능성을 말로 나타내면 어느 것인가요?","options":[{"t":"~일 것 같다","correct":true},{"t":"~아닐 것 같다","mis":"M5-2-u6-X12"},{"t":"반반이다","mis":"M5-2-u6-X12"},{"t":"확실하다","mis":"M5-2-u6-X12"}],"explanation":["첫째 회전판은 4칸 가운데 3칸이 색칠되어 있어요.","색칠한 칸이 없으면 불가능, 절반이면 반반, 모두면 확실이에요.","그래서 「~일 것 같다」예요."],"asset":{"type":"spin","n":4,"boards":[[0,1,2],[],[0,1],[0,1,2,3]]}},{"stem":"똑같이 4칸으로 나눈 회전판이에요. 넷째 회전판에서 화살이 색칠한 칸에 멈출 가능성을 말로 나타내면 어느 것인가요?","options":[{"t":"불가능하다","correct":true},{"t":"확실하다","mis":"M5-2-u6-X12"},{"t":"~아닐 것 같다","mis":"M5-2-u6-X12"},{"t":"반반이다","mis":"M5-2-u6-X12"}],"explanation":["넷째 회전판은 4칸 가운데 0칸이 색칠되어 있어요.","색칠한 칸이 없으면 불가능, 절반이면 반반, 모두면 확실이에요.","그래서 「불가능하다」예요."],"asset":{"type":"spin","n":4,"boards":[[0],[0,1,2,3],[0,1],[]]}}]}}'::jsonb),
