('g5_2_math_u6_review_d#15','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C4',2,'mc','auto','라 모둠의 한 달 운동 횟수 평균은 15회, 전체 초등학생의 평균은 12.8회예요. 바르게 해석한 것은 어느 것인가요?',ARRAY['M5-2-u6-X11','M5-2-u6-X03']::text[],true,'{"seq":15,"concept":"M5-2-u6-C4","difficulty":2,"kind":"mc","stem":"라 모둠의 한 달 운동 횟수 평균은 15회, 전체 초등학생의 평균은 12.8회예요. 바르게 해석한 것은 어느 것인가요?","options":[{"t":"라 모둠은 전체 초등학생보다 한 달 운동을 많이 한다고 볼 수 있다","correct":true},{"t":"라 모둠이 전체 초등학생보다 한 달 운동을 더 적게 한다","mis":"M5-2-u6-X11"},{"t":"라 모둠 친구는 모두 15회씩 한다","mis":"M5-2-u6-X03"},{"t":"라 모둠에는 12.8회 한 친구가 없다","mis":"M5-2-u6-X03"}],"explanation":["평균끼리 견주면 무리 전체의 경향을 말할 수 있어요.","15회와 12.8회를 견주면 라 모둠의 평균이 더 커요.","모두 그 값씩 한다는 뜻은 아니에요."],"variant_rule":{"alt":[{"stem":"나 모둠의 한 달 운동 횟수 평균은 10회, 전체 초등학생의 평균은 12.8회예요. 바르게 해석한 것은 어느 것인가요?","options":[{"t":"나 모둠은 전체 초등학생보다 한 달 운동을 적게 한다고 볼 수 있다","correct":true},{"t":"나 모둠이 전체 초등학생보다 한 달 운동을 더 많이 한다","mis":"M5-2-u6-X11"},{"t":"나 모둠 친구는 모두 10회씩 한다","mis":"M5-2-u6-X03"},{"t":"나 모둠에는 12.8회 한 친구가 없다","mis":"M5-2-u6-X03"}],"explanation":["평균끼리 견주면 무리 전체의 경향을 말할 수 있어요.","10회와 12.8회를 견주면 나 모둠의 평균이 더 작아요.","모두 그 값씩 한다는 뜻은 아니에요."]},{"stem":"가 모둠의 한 달 운동 횟수 평균은 14회, 전체 초등학생의 평균은 12.8회예요. 바르게 해석한 것은 어느 것인가요?","options":[{"t":"가 모둠은 전체 초등학생보다 한 달 운동을 많이 한다고 볼 수 있다","correct":true},{"t":"가 모둠이 전체 초등학생보다 한 달 운동을 더 적게 한다","mis":"M5-2-u6-X11"},{"t":"가 모둠 친구는 모두 14회씩 한다","mis":"M5-2-u6-X03"},{"t":"가 모둠에는 12.8회 한 친구가 없다","mis":"M5-2-u6-X03"}],"explanation":["평균끼리 견주면 무리 전체의 경향을 말할 수 있어요.","14회와 12.8회를 견주면 가 모둠의 평균이 더 커요.","모두 그 값씩 한다는 뜻은 아니에요."]}]}}'::jsonb),
('g5_2_math_u6_review_d#16','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C8',2,'sa','auto','표를 보고 세 해 동안 봄의 산불 횟수 평균을 반올림하여 일의 자리까지 나타내면 약 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M5-2-u6-C8","difficulty":2,"kind":"sa","stem":"표를 보고 세 해 동안 봄의 산불 횟수 평균을 반올림하여 일의 자리까지 나타내면 약 몇 회인가요? 숫자로 쓰세요.","answer":["302"],"explanation":["봄 칸만 골라요 — 377, 370, 158.","377 + 370 + 158 = 905예요.","905 ÷ 3을 계산하면 301.6…이고, 반올림하면 약 302예요."],"mis":"M5-2-u6-X17","asset":{"type":"passage","title":"2022~2024년 계절별 산불 횟수(회)","lines":["연도 | 봄 | 여름 | 가을 | 겨울 | 합계","2022년 | 377 | 29 | 61 | 289 | 756","2023년 | 370 | 12 | 48 | 166 | 596","2024년 | 158 | 35 | 26 | 60 | 279"],"numbered":false},"variant_rule":{"alt":[{"stem":"표를 보고 세 해 동안 여름의 산불 횟수 평균을 반올림하여 일의 자리까지 나타내면 약 몇 회인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["여름 칸만 골라요 — 29, 12, 35.","29 + 12 + 35 = 76이에요.","76 ÷ 3을 계산하면 25.3…이고, 반올림하면 약 25예요."],"asset":{"type":"passage","title":"2022~2024년 계절별 산불 횟수(회)","lines":["연도 | 봄 | 여름 | 가을 | 겨울 | 합계","2022년 | 377 | 29 | 61 | 289 | 756","2023년 | 370 | 12 | 48 | 166 | 596","2024년 | 158 | 35 | 26 | 60 | 279"],"numbered":false}},{"stem":"표를 보고 세 해 동안 봄의 미세먼지 나쁨 날수 평균을 구하면 며칠인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["봄 칸만 골라요 — 31, 27, 23.","31 + 27 + 23 = 81이에요.","81 ÷ 3 = 27이에요."],"asset":{"type":"passage","title":"2022~2024년 계절별 미세먼지 나쁨 날수(일)","lines":["연도 | 봄 | 여름 | 가을 | 겨울 | 합계","2022년 | 31 | 2 | 9 | 24 | 66","2023년 | 27 | 1 | 8 | 20 | 56","2024년 | 23 | 3 | 10 | 22 | 58"],"numbered":false}}]}}'::jsonb),
('g5_2_math_u6_review_d#17','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C3',3,'mc','auto','가 모둠 3명은 8점, 9점, 10점, 나 모둠 5명은 9점, 8점, 7점, 8점, 8점이에요. 한 사람당 받은 점수가 더 많은 쪽은 어느 쪽인가요?',ARRAY['M5-2-u6-X08','M5-2-u6-X07']::text[],true,'{"seq":17,"concept":"M5-2-u6-C3","difficulty":3,"kind":"mc","stem":"가 모둠 3명은 8점, 9점, 10점, 나 모둠 5명은 9점, 8점, 7점, 8점, 8점이에요. 한 사람당 받은 점수가 더 많은 쪽은 어느 쪽인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M5-2-u6-X08"},{"t":"두 쪽이 같다","mis":"M5-2-u6-X07"},{"t":"사람 수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["사람 수가 다르면 합이 아니라 평균으로 견줘요.","가 모둠 평균 27 ÷ 3 = 9, 나 모둠 평균 40 ÷ 5 = 8이에요.","한 사람당 더 많은 쪽은 가 모둠이에요."],"variant_rule":{"alt":[{"stem":"정아네 모둠 4명은 8개, 10개, 9개, 9개, 세호네 모둠 5명은 9개, 7개, 10개, 7개, 7개예요. 한 사람당 건 고리 수가 더 많은 쪽은 어느 쪽인가요?","options":[{"t":"정아네 모둠","correct":true},{"t":"세호네 모둠","mis":"M5-2-u6-X08"},{"t":"두 쪽이 같다","mis":"M5-2-u6-X07"},{"t":"사람 수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["사람 수가 다르면 합이 아니라 평균으로 견줘요.","정아네 모둠 평균 36 ÷ 4 = 9, 세호네 모둠 평균 40 ÷ 5 = 8이에요.","한 사람당 더 많은 쪽은 정아네 모둠이에요."]},{"stem":"가 모둠 4명은 9개, 10개, 8개, 9개, 나 모둠 5명은 8개, 7개, 9개, 8개, 8개예요. 한 사람당 넣은 공 수가 더 많은 쪽은 어느 쪽인가요?","options":[{"t":"가 모둠","correct":true},{"t":"나 모둠","mis":"M5-2-u6-X08"},{"t":"두 쪽이 같다","mis":"M5-2-u6-X07"},{"t":"사람 수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["사람 수가 다르면 합이 아니라 평균으로 견줘요.","가 모둠 평균 36 ÷ 4 = 9, 나 모둠 평균 40 ÷ 5 = 8이에요.","한 사람당 더 많은 쪽은 가 모둠이에요."]}]}}'::jsonb),
('g5_2_math_u6_review_d#18','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C3',3,'sa','auto','하린이가 일주일 동안 읽은 쪽수의 평균은 30쪽이에요. 월요일 32쪽, 화요일 25쪽, 수요일 40쪽, 금요일 35쪽일 때 목요일에 읽은 쪽수는 몇 쪽인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u6-C3","difficulty":3,"kind":"sa","stem":"하린이가 일주일 동안 읽은 쪽수의 평균은 30쪽이에요. 월요일 32쪽, 화요일 25쪽, 수요일 40쪽, 금요일 35쪽일 때 목요일에 읽은 쪽수는 몇 쪽인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["평균 × 자료 수 = 합 — 30 × 5 = 150이에요.","아는 값의 합은 32 + 25 + 40 + 35 = 132예요.","150 − 132 = 18이에요."],"mis":"M5-2-u6-X09","variant_rule":{"alt":[{"stem":"수현이가 8월부터 11월까지 저금한 금액의 평균은 3000원이에요. 9월 4500원, 10월 2000원, 11월 3000원일 때 8월에 저금한 금액은 몇 원인가요? 숫자로 쓰세요.","answer":["2500"],"explanation":["평균 × 자료 수 = 합 — 3000 × 4 = 12000이에요.","아는 값의 합은 4500 + 2000 + 3000 = 9500이에요.","12000 − 9500 = 2500이에요."]},{"stem":"라온이의 수학 단원평가 점수의 평균은 88점이에요. 1단원 88점, 2단원 92점, 4단원 96점일 때 3단원 점수는 몇 점인가요? 숫자로 쓰세요.","answer":["76"],"explanation":["평균 × 자료 수 = 합 — 88 × 4 = 352예요.","아는 값의 합은 88 + 92 + 96 = 276이에요.","352 − 276 = 76이에요."]}]}}'::jsonb),
('g5_2_math_u6_review_d#19','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C5',3,'mc','auto','㉠ 내일 아침에 해가 뜰 가능성.  ㉡ 파란 공 1개와 빨간 공 3개가 든 상자에서 공을 한 개 꺼낼 때 파란 공이 나올 가능성.  ㉢ 파란 공 1개와 빨간 공 1개가 든 상자에서 공을 한 개 꺼낼 때 파란 공이 나올 가능성. 이 일들을 일어날 가능성이 큰 것부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M5-2-u6-X18','M5-2-u6-X12']::text[],true,'{"seq":19,"concept":"M5-2-u6-C5","difficulty":3,"kind":"mc","stem":"㉠ 내일 아침에 해가 뜰 가능성.  ㉡ 파란 공 1개와 빨간 공 3개가 든 상자에서 공을 한 개 꺼낼 때 파란 공이 나올 가능성.  ㉢ 파란 공 1개와 빨간 공 1개가 든 상자에서 공을 한 개 꺼낼 때 파란 공이 나올 가능성. 이 일들을 일어날 가능성이 큰 것부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"㉠, ㉢, ㉡","correct":true},{"t":"㉡, ㉢, ㉠","mis":"M5-2-u6-X18"},{"t":"㉡, ㉠, ㉢","mis":"M5-2-u6-X12"},{"t":"㉢, ㉡, ㉠","mis":"M5-2-u6-X12"}],"explanation":["먼저 하나씩 말로 나타내 봐요 — ㉠ 확실하다, ㉡ ~아닐 것 같다, ㉢ 반반이다.","확실하다가 가장 크고 불가능하다가 가장 작아요.","큰 것부터 쓰면 ㉠, ㉢, ㉡예요."],"variant_rule":{"alt":[{"stem":"㉠ 끓는 물에 넣은 얼음이 녹을 가능성.  ㉡ 주사위를 굴려 5 이상인 수가 나올 가능성.  ㉢ 동전을 던질 때 그림면이 나올 가능성. 이 일들을 일어날 가능성이 큰 것부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"㉠, ㉢, ㉡","correct":true},{"t":"㉡, ㉢, ㉠","mis":"M5-2-u6-X18"},{"t":"㉡, ㉠, ㉢","mis":"M5-2-u6-X12"},{"t":"㉢, ㉡, ㉠","mis":"M5-2-u6-X12"}],"explanation":["먼저 하나씩 말로 나타내 봐요 — ㉠ 확실하다, ㉡ ~아닐 것 같다, ㉢ 반반이다.","확실하다가 가장 크고 불가능하다가 가장 작아요.","큰 것부터 쓰면 ㉠, ㉢, ㉡예요."]},{"stem":"㉠ 내일 아침에 살아 있는 용을 만날 가능성.  ㉡ 보통 달걀 하나를 깨뜨렸을 때 노른자가 1개일 가능성.  ㉢ 강아지 한 마리가 태어날 때 수컷일 가능성. 이 일들을 일어날 가능성이 큰 것부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"㉡, ㉢, ㉠","correct":true},{"t":"㉠, ㉢, ㉡","mis":"M5-2-u6-X18"},{"t":"㉡, ㉠, ㉢","mis":"M5-2-u6-X12"},{"t":"㉢, ㉡, ㉠","mis":"M5-2-u6-X12"}],"explanation":["먼저 하나씩 말로 나타내 봐요 — ㉠ 불가능하다, ㉡ ~일 것 같다, ㉢ 반반이다.","확실하다가 가장 크고 불가능하다가 가장 작아요.","큰 것부터 쓰면 ㉡, ㉢, ㉠예요."]}]}}'::jsonb),
('g5_2_math_u6_review_d#20','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C7',3,'mc','auto','회전판 가를 돌린 500명 가운데 100명이, 회전판 나를 돌린 200명 가운데 102명이 연필을 받았어요. 연필을 받고 싶다면 어느 회전판을 고르는 것이 더 유리할까요?',ARRAY['M5-2-u6-X16','M5-2-u6-X08']::text[],true,'{"seq":20,"concept":"M5-2-u6-C7","difficulty":3,"kind":"mc","stem":"회전판 가를 돌린 500명 가운데 100명이, 회전판 나를 돌린 200명 가운데 102명이 연필을 받았어요. 연필을 받고 싶다면 어느 회전판을 고르는 것이 더 유리할까요?","options":[{"t":"회전판 나","correct":true},{"t":"회전판 가","mis":"M5-2-u6-X16"},{"t":"어느 것을 골라도 같다","mis":"M5-2-u6-X16"},{"t":"돌린 사람 수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["받은 사람 수가 아니라 돌린 사람 가운데 얼마인지 견줘요.","가는 500명 가운데 100명으로 절반보다 적어요, 나는 200명 가운데 102명으로 절반보다 많아요.","그래서 회전판 나가 더 유리해요."],"variant_rule":{"alt":[{"stem":"회전판 가를 돌린 600명 가운데 150명이, 회전판 나를 돌린 250명 가운데 130명이 연필을 받았어요. 연필을 받고 싶다면 어느 회전판을 고르는 것이 더 유리할까요?","options":[{"t":"회전판 나","correct":true},{"t":"회전판 가","mis":"M5-2-u6-X16"},{"t":"어느 것을 골라도 같다","mis":"M5-2-u6-X16"},{"t":"돌린 사람 수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["받은 사람 수가 아니라 돌린 사람 가운데 얼마인지 견줘요.","가는 600명 가운데 150명으로 절반보다 적어요, 나는 250명 가운데 130명으로 절반보다 많아요.","그래서 회전판 나가 더 유리해요."]},{"stem":"회전판 가를 돌린 150명 가운데 80명이, 회전판 나를 돌린 500명 가운데 200명이 공책을 받았어요. 공책을 받고 싶다면 어느 회전판을 고르는 것이 더 유리할까요?","options":[{"t":"회전판 가","correct":true},{"t":"회전판 나","mis":"M5-2-u6-X16"},{"t":"어느 것을 골라도 같다","mis":"M5-2-u6-X16"},{"t":"돌린 사람 수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["받은 사람 수가 아니라 돌린 사람 가운데 얼마인지 견줘요.","가는 150명 가운데 80명으로 절반보다 많아요, 나는 500명 가운데 200명으로 절반보다 적어요.","그래서 회전판 가가 더 유리해요."]}]}}'::jsonb),
('g5_2_math_u6_review_d#21','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C8',3,'mc','auto','도서관 대출 권수의 평일 합은 300, 주말 합은 173이에요. 평일 평균은 60, 주말 평균은 약 87이에요. 바르게 알 수 있는 점은 어느 것인가요?',ARRAY['M5-2-u6-X08','M5-2-u6-X07']::text[],true,'{"seq":21,"concept":"M5-2-u6-C8","difficulty":3,"kind":"mc","stem":"도서관 대출 권수의 평일 합은 300, 주말 합은 173이에요. 평일 평균은 60, 주말 평균은 약 87이에요. 바르게 알 수 있는 점은 어느 것인가요?","options":[{"t":"하루에 견주면 주말이 더 많다고 볼 수 있다","correct":true},{"t":"합이 크므로 평일이 더 많다","mis":"M5-2-u6-X08"},{"t":"평일과 주말이 같다","mis":"M5-2-u6-X07"},{"t":"날수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["평일은 5일, 주말은 2일이라 합은 날수가 많은 평일이 커 보여요.","하루당 값인 평균으로 견줘요 — 60 < 87이에요.","그래서 주말이 더 많다고 볼 수 있어요."],"asset":{"type":"passage","title":"요일별 도서관 대출 권수(권)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","권 | 62 | 58 | 65 | 60 | 55 | 83 | 90"],"numbered":false},"variant_rule":{"alt":[{"stem":"산불 횟수의 평일 합은 175, 주말 합은 95예요. 평일 평균은 35, 주말 평균은 약 48이에요. 바르게 알 수 있는 점은 어느 것인가요?","options":[{"t":"하루에 견주면 주말이 더 많다고 볼 수 있다","correct":true},{"t":"합이 크므로 평일이 더 많다","mis":"M5-2-u6-X08"},{"t":"평일과 주말이 같다","mis":"M5-2-u6-X07"},{"t":"날수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["평일은 5일, 주말은 2일이라 합은 날수가 많은 평일이 커 보여요.","하루당 값인 평균으로 견줘요 — 35 < 48이에요.","그래서 주말이 더 많다고 볼 수 있어요."],"asset":{"type":"passage","title":"요일별 산불 횟수(회)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","회 | 37 | 35 | 28 | 36 | 39 | 41 | 54"],"numbered":false}},{"stem":"놀이터에 온 어린이 수의 평일 합은 200, 주말 합은 133이에요. 평일 평균은 40, 주말 평균은 약 67이에요. 바르게 알 수 있는 점은 어느 것인가요?","options":[{"t":"하루에 견주면 주말이 더 많다고 볼 수 있다","correct":true},{"t":"합이 크므로 평일이 더 많다","mis":"M5-2-u6-X08"},{"t":"평일과 주말이 같다","mis":"M5-2-u6-X07"},{"t":"날수가 달라 견줄 수 없다","mis":"M5-2-u6-X08"}],"explanation":["평일은 5일, 주말은 2일이라 합은 날수가 많은 평일이 커 보여요.","하루당 값인 평균으로 견줘요 — 40 < 67이에요.","그래서 주말이 더 많다고 볼 수 있어요."],"asset":{"type":"passage","title":"요일별 놀이터에 온 어린이 수(명)","lines":["요일 | 월 | 화 | 수 | 목 | 금 | 토 | 일","명 | 42 | 38 | 45 | 40 | 35 | 63 | 70"],"numbered":false}}]}}'::jsonb),
('g5_2_math_u6_review_d#22','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C2',3,'mc','auto','5학년 반별 학생 수는 1반 23명, 2반 21명, 3반 21명, 4반 19명, 5반 22명, 6반 20명이에요. 이 자료의 평균은 얼마인가요?',ARRAY['M5-2-u6-X05','M5-2-u6-X01','M5-2-u6-X06']::text[],true,'{"seq":22,"concept":"M5-2-u6-C2","difficulty":3,"kind":"mc","stem":"5학년 반별 학생 수는 1반 23명, 2반 21명, 3반 21명, 4반 19명, 5반 22명, 6반 20명이에요. 이 자료의 평균은 얼마인가요?","options":[{"t":"21명","correct":true},{"t":"126명","mis":"M5-2-u6-X05"},{"t":"23명","mis":"M5-2-u6-X01"},{"t":"18명","mis":"M5-2-u6-X06"}],"explanation":["합은 23 + 21 + 21 + 19 + 22 + 20 = 126이에요.","자료 수는 6이에요.","평균은 126 ÷ 6 = 21이에요."],"variant_rule":{"alt":[{"stem":"해양 박물관에 방문한 초등학생 수는 9월 714명, 10월 525명, 11월 651명, 12월 770명이에요. 이 자료의 평균은 얼마인가요?","options":[{"t":"665명","correct":true},{"t":"2660명","mis":"M5-2-u6-X05"},{"t":"770명","mis":"M5-2-u6-X01"},{"t":"532명","mis":"M5-2-u6-X06"}],"explanation":["합은 714 + 525 + 651 + 770 = 2660이에요.","자료 수는 4예요.","평균은 2660 ÷ 4 = 665예요."]},{"stem":"도윤이의 줄넘기 기록은 첫째 84번, 둘째 95번, 셋째 102번, 넷째 88번, 다섯째 91번, 여섯째 92번이에요. 이 자료의 평균은 얼마인가요?","options":[{"t":"92번","correct":true},{"t":"552번","mis":"M5-2-u6-X05"},{"t":"102번","mis":"M5-2-u6-X01"},{"t":"93번","mis":"M5-2-u6-X07"}],"explanation":["합은 84 + 95 + 102 + 88 + 91 + 92 = 552예요.","자료 수는 6이에요.","평균은 552 ÷ 6 = 92예요."]}]}}'::jsonb),
('g5_2_math_u6_review_d#23','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C2',4,'essay','teacher','수호가 지난주 요일별로 손을 씻은 횟수는 7회, 8회, 6회, 7회, 6회, 8회, 7회예요. 평균을 구하는 과정을 식과 함께 쓰고, 「평균은 7회이지만 7회가 아닌 날도 있다」는 말이 맞는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u6-C2","difficulty":4,"kind":"essay","stem":"수호가 지난주 요일별로 손을 씻은 횟수는 7회, 8회, 6회, 7회, 6회, 8회, 7회예요. 평균을 구하는 과정을 식과 함께 쓰고, 「평균은 7회이지만 7회가 아닌 날도 있다」는 말이 맞는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 합은 7 + 8 + 6 + 7 + 6 + 8 + 7 = 49이고 자료 수는 7이므로 평균은 49 ÷ 7 = 7(회)이다. 평균은 자룟값을 고르게 한 값이므로 6회나 8회인 날처럼 7회가 아닌 날이 있어도 된다. 그래서 그 말은 맞다.","scoring_points":["합 49를 구했는가","49 ÷ 7 = 7(회)로 평균을 구했는가","평균은 고르게 한 값이라 7회가 아닌 날도 있다고 썼는가"]},"explanation":["합은 49예요.","49 ÷ 7 = 7(회)이에요.","평균은 고르게 한 값이라 모두 7회는 아니에요."]}'::jsonb),
('g5_2_math_u6_review_d#24','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C6',4,'essay','teacher','「확실하다」, 「반반이다」, 「불가능하다」를 각각 수로 나타내고, 주사위를 한 번 굴릴 때 일어날 수 있는 일을 하나씩 들어 0, ⟨1/2⟩, 1인 가능성의 예를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u6-C6","difficulty":4,"kind":"essay","stem":"「확실하다」, 「반반이다」, 「불가능하다」를 각각 수로 나타내고, 주사위를 한 번 굴릴 때 일어날 수 있는 일을 하나씩 들어 0, ⟨1/2⟩, 1인 가능성의 예를 쓰세요.","answer_guide":{"answer":"예: 확실하다는 1, 반반이다는 ⟨1/2⟩, 불가능하다는 0으로 나타낸다. 주사위를 굴려 6 이하인 수가 나올 가능성은 1이다. 홀수가 나올 가능성은 홀수와 짝수가 3개씩이라 반반이므로 ⟨1/2⟩이다. 7이 나올 가능성은 7이 없어 불가능하므로 0이다.","scoring_points":["세 말을 1·⟨1/2⟩·0으로 바르게 나타냈는가","가능성이 1인 예와 0인 예를 들었는가","가능성이 ⟨1/2⟩인 예를 까닭과 함께 들었는가"]},"explanation":["확실하다 1, 반반이다 ⟨1/2⟩, 불가능하다 0이에요.","6 이하 → 1, 7 → 0이에요.","홀수 → ⟨1/2⟩이에요."]}'::jsonb),
('g5_2_math_u6_review_d#25','math',5,2,'u6','','g5_2_math_u6_review_d','unit_review','M5-2-u6-C3',4,'sa','auto','하린이 지금까지 받은 점수는 92점, 84점, 90점이에요. 한 번 더 시험을 보아 4번의 평균이 90점이 되려면 마지막 시험에서 몇 점을 받아야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u6-C3","difficulty":4,"kind":"sa","stem":"하린이 지금까지 받은 점수는 92점, 84점, 90점이에요. 한 번 더 시험을 보아 4번의 평균이 90점이 되려면 마지막 시험에서 몇 점을 받아야 하나요? 숫자로 쓰세요.","answer":["94"],"explanation":["평균 90점이 되려면 합이 90 × 4 = 360(점)이어야 해요.","지금까지의 합은 92 + 84 + 90 = 266이에요.","360 − 266 = 94(점)이에요."],"mis":"M5-2-u6-X09","variant_rule":{"alt":[{"stem":"라온이 지금까지 받은 점수는 88점, 92점, 76점이에요. 한 번 더 시험을 보아 4번의 평균이 88점이 되려면 마지막 시험에서 몇 점을 받아야 하나요? 숫자로 쓰세요.","answer":["96"],"explanation":["평균 88점이 되려면 합이 88 × 4 = 352(점)이어야 해요.","지금까지의 합은 88 + 92 + 76 = 256이에요.","352 − 256 = 96(점)이에요."]},{"stem":"서연이 지금까지 받은 점수는 75점, 90점, 85점이에요. 한 번 더 시험을 보아 4번의 평균이 85점이 되려면 마지막 시험에서 몇 점을 받아야 하나요? 숫자로 쓰세요.","answer":["90"],"explanation":["평균 85점이 되려면 합이 85 × 4 = 340(점)이어야 해요.","지금까지의 합은 75 + 90 + 85 = 250이에요.","340 − 250 = 90(점)이에요."]}]}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SC5-2-u1-C1','sci',5,2,'u1',1,'한 가지 물질과 섞여 있는 물질 — 우리 주변 물질에는 한 가지 물질로만 이루어진 것(금관의 금, 못의 철, 얼음의 물, 산소)과 두 가지 이상의 물질이 섞여 있는 것(소금물 — 소금과 물, 공기 — 질소·산소·이산화 탄소 등, 탄산음료 — 물과 이산화 탄소 등, 바닷가 흙, 유성 물감 — 기름과 색소 등)이 있음 · 겉모습(차가움·딱딱함·색)이 아니라 무엇으로 되어 있는지로 나눔 · 눈에 보이지 않게 섞인 것도 섞여 있는 물질',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],1),
('SC5-2-u1-C2','sci',5,2,'u1',2,'혼합물의 뜻 — 두 가지 이상의 물질이 각각의 성질이 변하지 않은 채 섞여 있는 것 · 소금물 속 소금은 여전히 짜고 설탕물 속 설탕은 여전히 닮 · 성질이 그대로라서 그 차이를 이용해 나눌 수 있음',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],2),
('SC5-2-u1-C3','sci',5,2,'u1',2,'혼합물에서 얻는 물질과 쓰임 — 바닷물 → 소금(음식)·마실 물, 사탕수수 → 설탕(사탕·시럽), 금광석 → 금, 고무나무 → 천연고무액(지우개), 목화 → 목화솜(옷·이불), 콩 → 콩 단백질(두부·콩고기) · 얻은 물질은 그대로 쓰거나 가공해 필요한 물건을 만듦 · 병원에서는 혈액을 여러 성분으로 나누어 치료·연구에 씀',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],3),
('SC5-2-u1-C4','sci',5,2,'u1',2,'혼합물을 분리하는 까닭 — 여러 물질이 섞여 있으므로 나누어야 필요한 물질을 얻어 쓸 수 있음 · 분리배출도 물질별로 나누어 다시 얻어 쓰려는 것과 닮음 · 옛날 키·풍구로 곡식과 쭉정이·티끌을 나눈 것도 같은 까닭 · 「주변 물질이 모두 혼합물이라서」는 옳지 않음(한 가지 물질도 있음)',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],4),
('SC5-2-u1-C5','sci',5,2,'u1',3,'모래와 자갈의 관찰 — 모양과 색깔은 둘 다 여러 가지라 그것으로는 나누기 어렵고, 가장 뚜렷한 차이는 알갱이의 크기(모래가 자갈보다 작음) · 체로 나눈 모래·자갈도 여러 알갱이가 섞여 있어 여전히 섞여 있는 물질',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],5),
('SC5-2-u1-C6','sci',5,2,'u1',3,'체로 고체 혼합물 분리하기 — 알갱이의 크기가 다른 고체 혼합물은 크기 차이를 이용해 체로 나눔 · 체의 눈보다 작은 알갱이는 빠져나가고 큰 알갱이는 체에 남음 · 체의 눈은 작은 알갱이보다 크고 큰 알갱이보다 작아야 함(밀가루 체처럼 너무 촘촘하면 모두 남고, 너무 크면 모두 빠져나감) · 손으로 고르는 것보다 양이 많아도 한 번에 빠르게 나눔',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],6),
('SC5-2-u1-C7','sci',5,2,'u1',3,'생활 속 체와 여러 번 거르기 — 강에서 조개 잡기(모래는 빠지고 조개가 남음), 해변 쓰레기 수거 장비(모래는 돌아가고 쓰레기가 남음), 마스크(공기는 지나가고 황사·먼지는 걸림) · 세 가지 이상이 섞이면 눈 크기가 다른 체를 차례로 써서 한 번에 하나씩 나눔(좁쌀 < 쌀 < 팥이면 체 두 개)',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],7),
('SC5-2-u1-C8','sci',5,2,'u1',4,'섞이지 않는 물과 기름 — 물과 기름은 골고루 섞이지 않고 층을 이루어 기름이 위쪽, 물이 아래쪽에 있음 · 기름을 먼저 붓고 물을 부어도, 세게 흔들어 잠깐 뿌옇게 되어도 시간이 지나면 다시 층을 이룸 · 섞이지 않는 까닭은 이 단원에서 다루지 않음',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],8),
('SC5-2-u1-C9','sci',5,2,'u1',4,'스포이트로 분리하기 — 위층의 기름을 스포이트로 뽑아 빈 그릇에 옮기기를 되풀이해 물과 기름을 각각 얻음 · 경계면 가까이는 물이 섞여 들지 않게 조심하고 따로 모음 · 뽑아 옮긴 기름은 다시 쓸 수 있음',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],9),
('SC5-2-u1-C10','sci',5,2,'u1',4,'흡착포와 두 도구 견주기 — 흡착포는 기름을 흡수하는 종이로, 물 위에 뜬 기름에 대면 기름만 빨아들여 물을 깨끗이 남김(얇게 넓게 퍼진 기름에 편함, 흡수한 기름은 다시 쓰기 어려움) · 바다 기름 유출 때 흡착포를 쓰고 울타리를 침 · 상황에 맞는 도구를 고름 · 마블링·국 위 기름 떠내기도 위에 뜨는 성질을 이용',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],10),
('SC5-2-u1-C11','sci',5,2,'u1',5,'소금과 모래의 성질 차이 — 소금과 모래는 알갱이 크기가 비슷해 체로 나누기 어려움 · 소금은 물에 녹고 모래는 물에 녹지 않음 → 이 차이를 이용해 나눔 · 물에 녹은 소금은 없어진 것이 아니라 물속에 섞여 있음',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],11),
('SC5-2-u1-C12','sci',5,2,'u1',5,'거름 — 물에 녹는 물질과 녹지 않는 물질을 걸러서 나누는 방법 · 소금과 모래를 물에 녹여 저은 뒤 거름 장치로 거르면 모래는 거름종이 위에 남고 소금물은 빠져나감 · 거름종이를 접어 깔때기에 물을 묻혀 붙이고, 유리 막대를 따라 천천히 붓고, 깔때기 끝을 비커 옆면에 댐',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],12),
('SC5-2-u1-C13','sci',5,2,'u1',5,'증발과 안전 — 거름종이를 빠져나간 소금물을 증발 접시에 담아 가열하면 물이 증발하고 녹아 있던 소금이 하얗게 남음 · 차례는 물에 녹이기 → 거름 → 증발 · 약하게 가열하고 보안경·면장갑을 끼며 증발 접시는 집게로 옮기고, 전원을 끈 가열판도 뜨거우니 만지지 않음',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],13),
('SC5-2-u1-C14','sci',5,2,'u1',5,'생활 속 거름과 증발 — 장 담그기에서 천으로 걸러 간장을 얻음(거름) · 치즈를 만들 때 천으로 걸러 냄(거름) · 염전에서 바닷물을 가두어 햇빛과 바람으로 물을 증발시켜 소금을 얻음(증발 장치를 크게 만든 것과 같음) · 바닷가 신발에 남은 하얀 알갱이도 물이 증발하고 남은 소금',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],14),
('SC5-2-u1-C15','sci',5,2,'u1',6,'해수 담수화 장치 — 바닷물에는 소금 등이 섞여 있어 그대로 마실 수 없음 · 해수 담수화 장치는 바닷물에서 소금 등을 나누어 마실 물과 생활용수를 만듦 · 가뭄이 들거나 바다로 둘러싸인 섬 마을처럼 물이 모자란 곳에 꼭 필요함',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],15),
('SC5-2-u1-C16','sci',5,2,'u1',6,'혼합물의 분리를 이용한 장치와 지속가능한 삶 — 정수 장치(여러 겹 거름망으로 물속 오염 물질을 거름), 하수 처리 시설(오염된 물을 나누어 다시 씀), 공기 정화 장치(필터로 공기 속 먼지를 거름), 인공지능 폐기물 선별 장치(카메라로 보고 플라스틱·종이·유리를 골라 냄) · 장치는 물질의 성질을 바꾸지 않고 나눔 · 깨끗한 물과 공기로 건강을 지키고 자원을 다시 써 지속가능한 삶을 도움 · 실험실의 체·거름·증발이 큰 장치로 쓰임',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],16),
('SC5-2-u1-C17','sci',5,2,'u1',6,'장치 조사 보고서와 출처 — 장치를 하나 골라 쓰임·개발 배경(어떤 상황에서 왜 만들었나)·분리 원리·효과를 조사함 · 장치 고르기 → 조사하기 → 보고서 쓰기 → 공유하기 · 믿을 수 있는 자료를 쓰고 출처를 밝히며 내 말로 정리함',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],17),
('SC5-2-u1-C18','sci',5,2,'u1',7,'분리 장치 소개 포스터 — 계획하기(장치·역할 정하기) → 해 보기(디자인 앱으로 만들기) → 나누기(공유하고 댓글 달기) · 어떤 방법으로 무엇을 무엇에서 나누는지가 가장 크게 드러나야 함 · 장치 이름·분리 방법·개발 배경·출처를 넣고 개인 정보는 넣지 않음 · 보는 사람에 맞게 쉬운 말과 그림 화살표를 씀',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],18),
('SC5-2-u1-C19','sci',5,2,'u1',7,'공유와 댓글 예절 — 다른 모둠 포스터에 새로 알게 된 점·궁금한 점·구체적인 칭찬과 고칠 방향을 바르고 고운 말로 씀 · 「별로야」처럼 까닭 없는 말, 친구 개인 정보는 쓰지 않음 · 모둠원이 역할을 나누어 모두 참여함',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],19),
('SC5-2-u1-C20','sci',5,2,'u1',8,'새활용 — 버려지는 물건에 아이디어나 디자인을 더해 새로운 가치를 만드는 것(페트병 뚜껑 벽화, 안 쓰는 천으로 만든 가방, 플라스틱 병 조명) · 재활용은 녹이거나 부수어 변형해 다시 쓰는 것이고, 새활용은 에너지와 자원을 더 아낌 · 쓸 수 있는 재료를 먼저 나누어 골라 모음 · 업사이클링 아티스트는 버린 물건을 작품으로 바꿈',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],20),
('SC5-2-u1-C21','sci',5,2,'u1',8,'성질에 맞는 분리 방법 고르기 — 혼합물은 섞인 물질의 서로 다른 성질을 이용해 나눔: 알갱이 크기 차이 → 체 · 섞이지 않고 위에 뜸 → 스포이트·흡착포 · 물에 녹는지 → 거름 → 증발 · 도구보다 성질을 먼저 살피고, 여러 가지가 섞이면 방법을 알맞은 차례로 이어 씀',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],21)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SC5-2-u1-X01','sci',5,'u1',ARRAY['SC5-2-u1-C1']::text[],'눈에 보이지 않게 섞인 것을 한 가지 물질로 여긴다(공기·탄산음료·소금물을 한 가지라고)','보이지 않아도 섞여 있어요'),
('SC5-2-u1-X02','sci',5,'u1',ARRAY['SC5-2-u1-C1']::text[],'무엇으로 되어 있는지가 아니라 겉모습(차가움·딱딱함·색)으로 한 가지 물질과 섞인 물질을 나눈다','무엇으로 되어 있나'),
('SC5-2-u1-X03','sci',5,'u1',ARRAY['SC5-2-u1-C2']::text[],'물질이 섞이면 새 물질이 되어 성질이 바뀐다고 여긴다','성질이 그대로인 채 섞여요'),
('SC5-2-u1-X04','sci',5,'u1',ARRAY['SC5-2-u1-C2','SC5-2-u1-C11']::text[],'물에 녹은 물질은 없어졌다고 여긴다(녹은 소금·설탕은 사라졌다고)','녹아서 보이지 않을 뿐 섞여 있어요'),
('SC5-2-u1-X05','sci',5,'u1',ARRAY['SC5-2-u1-C3']::text[],'혼합물과 그 혼합물에서 얻는 물질을 바꾸어 짝짓는다(고무나무에서 금, 사탕수수에서 소금)','바닷물 소금 · 사탕수수 설탕 · 고무나무 천연고무액'),
('SC5-2-u1-X06','sci',5,'u1',ARRAY['SC5-2-u1-C4']::text[],'혼합물을 분리하는 까닭을 엉뚱하게 든다(무겁게·예쁘게·양을 늘리려고)','필요한 물질을 얻으려고'),
('SC5-2-u1-X07','sci',5,'u1',ARRAY['SC5-2-u1-C1','SC5-2-u1-C4']::text[],'우리 주변 물질은 모두 혼합물이라고 여긴다','한 가지 물질도 있어요'),
('SC5-2-u1-X08','sci',5,'u1',ARRAY['SC5-2-u1-C5']::text[],'모래와 자갈을 색깔이나 모양으로 나눌 수 있다고 여긴다','색·모양은 둘 다 여러 가지 · 크기'),
('SC5-2-u1-X09','sci',5,'u1',ARRAY['SC5-2-u1-C6','SC5-2-u1-C7']::text[],'체의 눈 크기 조건을 놓친다(눈이 작을수록, 또는 클수록 좋다고)','작은 알갱이 < 눈 < 큰 알갱이'),
('SC5-2-u1-X10','sci',5,'u1',ARRAY['SC5-2-u1-C6']::text[],'체에 남는 것과 빠져나가는 것을 거꾸로 안다','작으면 빠지고 크면 남아요'),
('SC5-2-u1-X11','sci',5,'u1',ARRAY['SC5-2-u1-C5']::text[],'체로 나누어 얻은 모래나 자갈은 이제 한 가지 물질이라고 여긴다','모래도 여러 알갱이가 섞여 있어요'),
('SC5-2-u1-X12','sci',5,'u1',ARRAY['SC5-2-u1-C7']::text[],'체 하나로 세 가지 이상을 한 번에 나눌 수 있다고 여긴다','한 번에 하나씩 · 체를 차례로'),
('SC5-2-u1-X13','sci',5,'u1',ARRAY['SC5-2-u1-C8']::text[],'물과 기름을 세게 흔들거나 저으면 골고루 섞인다고 여긴다','잠깐 뿌옇다가 다시 층'),
('SC5-2-u1-X14','sci',5,'u1',ARRAY['SC5-2-u1-C8']::text[],'물과 기름의 층을 거꾸로 안다(물이 위, 기름이 아래)','기름 위 · 물 아래'),
('SC5-2-u1-X15','sci',5,'u1',ARRAY['SC5-2-u1-C9']::text[],'스포이트 쓰는 법을 놓친다(아래층부터 깊이 넣거나 경계면을 신경 쓰지 않음)','위층부터 · 경계면 조심'),
('SC5-2-u1-X16','sci',5,'u1',ARRAY['SC5-2-u1-C10']::text[],'스포이트와 흡착포의 좋은 점·아쉬운 점을 거꾸로 안다(흡착포로 얻은 기름을 바로 다시 쓴다고)','스포이트 다시 씀 · 흡착포 얇은 기름'),
('SC5-2-u1-X17','sci',5,'u1',ARRAY['SC5-2-u1-C8','SC5-2-u1-C10']::text[],'섞이지 않는 액체 혼합물에 맞지 않는 방법(체·데우기 등)을 고른다','위에 뜬 쪽을 걷어 내요'),
('SC5-2-u1-X18','sci',5,'u1',ARRAY['SC5-2-u1-C11']::text[],'소금과 모래를 체로 나눌 수 있다고 여긴다','크기가 비슷해요 · 물에 녹는지'),
('SC5-2-u1-X19','sci',5,'u1',ARRAY['SC5-2-u1-C12']::text[],'거름종이 위에 소금이 남는다고 여기거나, 빠져나간 액체에 소금이 없다고 여긴다','모래는 위 · 소금은 물과 함께 아래'),
('SC5-2-u1-X20','sci',5,'u1',ARRAY['SC5-2-u1-C12','SC5-2-u1-C13']::text[],'거름과 증발의 차례나 쓰임을 바꾸어 안다','녹이기 → 거름 → 증발'),
('SC5-2-u1-X21','sci',5,'u1',ARRAY['SC5-2-u1-C13']::text[],'가열 실험의 안전 수칙을 놓친다(세게 가열, 맨손, 끈 가열판 만지기)','약하게 · 집게 · 끈 뒤에도 뜨거움'),
('SC5-2-u1-X22','sci',5,'u1',ARRAY['SC5-2-u1-C14']::text[],'생활 속 거름·증발의 예를 바꾸어 짝짓는다(염전을 거름, 간장 거르기를 증발로)','천으로 거르기 · 햇빛과 바람으로 증발'),
('SC5-2-u1-X23','sci',5,'u1',ARRAY['SC5-2-u1-C12']::text[],'거름 장치를 꾸미는 법을 놓친다(거름종이를 붙이지 않거나 한꺼번에 쏟음)','물 묻혀 붙이기 · 유리 막대 · 옆면'),
('SC5-2-u1-X24','sci',5,'u1',ARRAY['SC5-2-u1-C15']::text[],'해수 담수화 장치가 하는 일을 잘못 안다(소금을 넣는다고, 바닷물을 그대로 마셔도 된다고)','바닷물에서 소금 등을 나눠요'),
('SC5-2-u1-X25','sci',5,'u1',ARRAY['SC5-2-u1-C16']::text[],'혼합물의 분리는 실험실에서만 쓰는 방법이라고 여긴다','정수기·마스크·공기 청정기'),
('SC5-2-u1-X26','sci',5,'u1',ARRAY['SC5-2-u1-C16']::text[],'분리 장치와 그 장치가 나누는 것을 바꾸어 짝짓는다(공기 청정기가 물을, 정수 장치가 공기를)','무엇에서 무엇을 나누나'),
('SC5-2-u1-X27','sci',5,'u1',ARRAY['SC5-2-u1-C16']::text[],'분리 장치가 물질의 성질을 바꾼다고 여긴다','성질은 그대로 나누기만'),
('SC5-2-u1-X28','sci',5,'u1',ARRAY['SC5-2-u1-C17']::text[],'조사 자료를 출처 없이 그대로 옮기거나 믿을 수 있는지 따지지 않는다','출처 · 내 말로'),
('SC5-2-u1-X29','sci',5,'u1',ARRAY['SC5-2-u1-C18']::text[],'포스터에 이름·사진·꾸미기만 크게 넣고 분리 방법을 드러내지 않는다','무엇을 어떻게 나누는지'),
('SC5-2-u1-X30','sci',5,'u1',ARRAY['SC5-2-u1-C19']::text[],'까닭 없는 말·흉보는 말·개인 정보를 댓글이나 포스터에 쓴다','새로 안 점 · 바르고 고운 말'),
('SC5-2-u1-X31','sci',5,'u1',ARRAY['SC5-2-u1-C20']::text[],'재활용과 새활용을 같은 것으로 안다','녹이고 부수기 ↔ 아이디어 더하기'),
('SC5-2-u1-X32','sci',5,'u1',ARRAY['SC5-2-u1-C20']::text[],'새활용을 낡은 물건을 그대로 쓰는 것으로 여기거나 재료를 나누어 모으는 단계를 빠뜨린다','나누어 모으고 새 가치를'),
('SC5-2-u1-X33','sci',5,'u1',ARRAY['SC5-2-u1-C21']::text[],'섞인 물질의 성질을 따지지 않고 맞지 않는 방법이나 성질(자석·색깔 등)을 고른다','성질 먼저 → 방법'),
('SC5-2-u1-X34','sci',5,'u1',ARRAY['SC5-2-u1-C13','SC5-2-u1-C21']::text[],'여러 방법을 이어 쓸 때 차례를 놓친다(증발을 맨 처음에 함)','크기 → 녹이기·거름 → 증발'),
('SC5-2-u1-X35','sci',5,'u1',ARRAY['SC5-2-u1-C16']::text[],'분리 장치의 좋은 점을 편리함 하나로만 보아 건강·환경·자원의 가치를 놓친다','깨끗한 물·공기 · 자원 다시 쓰기')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_2_sci_u1_L01_basic#1','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',1,'mc','auto','두 가지 이상의 물질이 섞여 있는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"mc","stem":"두 가지 이상의 물질이 섞여 있는 것은 어느 것인가요?","options":[{"t":"소금물","correct":true},{"t":"금관","mis":"SC5-2-u1-X02"},{"t":"못","mis":"SC5-2-u1-X02"},{"t":"산소","mis":"SC5-2-u1-X01"}],"explanation":["소금물에는 소금이 있어요.","물도 있어요.","두 가지가 섞였어요."]}'::jsonb),
('g5_2_sci_u1_L01_basic#2','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',1,'mc','auto','한 가지 물질로만 이루어진 것은 어느 것인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X02']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"mc","stem":"한 가지 물질로만 이루어진 것은 어느 것인가요?","options":[{"t":"금관","correct":true},{"t":"공기","mis":"SC5-2-u1-X01"},{"t":"탄산음료","mis":"SC5-2-u1-X01"},{"t":"바닷가 흙","mis":"SC5-2-u1-X02"}],"explanation":["금관은 금으로 만들어요.","금 한 가지예요.","한 가지 물질이에요."]}'::jsonb),
