('g5_2_sci_u1_L08_basic#4','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C21',1,'ox','auto','물과 기름처럼 섞이지 않는 액체 혼합물은 스포이트로 나눌 수 있어요.',ARRAY['SC5-2-u1-X33']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C21","difficulty":1,"kind":"ox","stem":"물과 기름처럼 섞이지 않는 액체 혼합물은 스포이트로 나눌 수 있어요.","answer":"O","reason_options":[{"t":"위층 액체만 뽑아 다른 그릇으로 옮길 수 있기 때문에","correct":true},{"t":"스포이트는 고체 알갱이만 나누는 도구이기 때문에","mis":"SC5-2-u1-X33"}],"mis":"SC5-2-u1-X33","explanation":["기름은 위에 있어요.","스포이트로 뽑아요.","나눌 수 있어요."]}'::jsonb),
('g5_2_sci_u1_L08_basic#5','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C20',2,'mc','auto','페트병 뚜껑으로 벽화를 만들 때 가장 먼저 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X31','SC5-2-u1-X32']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C20","difficulty":2,"kind":"mc","stem":"페트병 뚜껑으로 벽화를 만들 때 가장 먼저 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"뚜껑을 씻어 색깔별로 나누어 모은다","correct":true},{"t":"뚜껑을 모두 녹인다","mis":"SC5-2-u1-X31"},{"t":"뚜껑을 다른 쓰레기와 섞어 둔다","mis":"SC5-2-u1-X32"},{"t":"뚜껑을 그냥 버린다","mis":"SC5-2-u1-X32"}],"explanation":["재료부터 모아요.","색깔별로 나눠요.","그다음 꾸며요."]}'::jsonb),
('g5_2_sci_u1_L08_basic#6','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C21',2,'blank','auto','혼합물의 분리 정리판에서 ㉢에 들어갈 말은 어느 것인가요?',ARRAY['SC5-2-u1-X20','SC5-2-u1-X33']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C21","difficulty":2,"kind":"blank","stem":"혼합물의 분리 정리판에서 ㉢에 들어갈 말은 어느 것인가요?","options":[{"t":"증발","correct":true},{"t":"체","mis":"SC5-2-u1-X20"},{"t":"흡착포","mis":"SC5-2-u1-X33"},{"t":"스포이트","mis":"SC5-2-u1-X33"}],"explanation":["소금과 모래 줄이에요.","거름 다음이에요.","증발이에요."],"asset":{"type":"passage","lines":["모래와 자갈 — (㉠) 차이 — 체","물과 기름 — 섞이지 않고 위에 뜸 — (㉡)·흡착포","소금과 모래 — 물에 녹는지 — 거름 → (㉢)"],"title":"혼합물의 분리 정리판"}}'::jsonb),
('g5_2_sci_u1_L08_basic#7','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C20',2,'mc','auto','다시 쓰는 여러 방법 자료에서 새활용이 아닌 것은 어느 것인가요?',ARRAY['SC5-2-u1-X31']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C20","difficulty":2,"kind":"mc","stem":"다시 쓰는 여러 방법 자료에서 새활용이 아닌 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"SC5-2-u1-X31"},{"t":"다","mis":"SC5-2-u1-X31"},{"t":"라","mis":"SC5-2-u1-X31"}],"explanation":["가는 부수고 녹여요.","그것은 재활용이에요.","나·다·라가 새활용이에요."],"asset":{"type":"passage","lines":["가 — 페트병을 잘게 부수고 녹여 옷감을 만든다.","나 — 안 쓰는 청바지로 가방을 만든다.","다 — 페트병 뚜껑을 색깔별로 모아 벽화를 만든다.","라 — 플라스틱 병 모양을 살려 물방울 조명을 만든다."],"title":"다시 쓰는 여러 방법"}}'::jsonb),
