('g5_2_sci_u1_L08_challenge#8','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C21',4,'mc','auto','「혼합물의 분리」 단원을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X33','SC5-2-u1-X25']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C21","difficulty":4,"kind":"mc","stem":"「혼합물의 분리」 단원을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"혼합물은 섞인 물질의 서로 다른 성질(크기·섞이지 않음·물에 녹음)을 이용해 나누고, 이 방법이 생활 속 장치와 새활용으로 이어진다","correct":true},{"t":"혼합물은 한 번 섞이면 다시 나눌 수 없다","mis":"SC5-2-u1-X03"},{"t":"어떤 혼합물이든 체 하나로 모두 나눌 수 있다","mis":"SC5-2-u1-X33"},{"t":"혼합물의 분리는 실험실에서만 쓰인다","mis":"SC5-2-u1-X25"}],"explanation":["성질 차이로 나눠요.","방법이 여러 가지예요.","생활에 쓰여요."]}'::jsonb),
