('g5_2_sci_u1_review_d#18','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C10',3,'mc','auto','물과 식용유를 나눈 뒤 식용유를 다시 요리에 쓰려고 해요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-2-u1-X16','SC5-2-u1-X17','SC5-2-u1-X13']::text[],false,'{"seq":18,"concept":"SC5-2-u1-C10","difficulty":3,"kind":"mc","stem":"물과 식용유를 나눈 뒤 식용유를 다시 요리에 쓰려고 해요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"스포이트로 위층 식용유를 뽑아 깨끗한 그릇에 옮긴다","correct":true},{"t":"흡착포로 빨아들인 뒤 꼭 짜서 쓴다","mis":"SC5-2-u1-X16"},{"t":"체로 거른다","mis":"SC5-2-u1-X17"},{"t":"세게 저어 섞은 뒤 쓴다","mis":"SC5-2-u1-X13"}],"explanation":["다시 써야 해요.","그대로 옮겨요.","스포이트예요."]}'::jsonb),
('g5_2_sci_u1_review_d#19','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C12',3,'mc','auto','설탕과 모래가 섞인 혼합물에서 설탕을 얻으려고 해요. 설탕도 물에 녹을 때, 알맞은 차례는 어느 것인가요?',ARRAY['SC5-2-u1-X34','SC5-2-u1-X18','SC5-2-u1-X20']::text[],false,'{"seq":19,"concept":"SC5-2-u1-C12","difficulty":3,"kind":"mc","stem":"설탕과 모래가 섞인 혼합물에서 설탕을 얻으려고 해요. 설탕도 물에 녹을 때, 알맞은 차례는 어느 것인가요?","options":[{"t":"물에 녹이기 → 거름으로 모래 걸러 내기 → 설탕물에서 물 증발시키기","correct":true},{"t":"증발 → 물에 녹이기 → 거름","mis":"SC5-2-u1-X34"},{"t":"체로 거르기 → 끝","mis":"SC5-2-u1-X18"},{"t":"거름 → 물에 녹이기 → 끝","mis":"SC5-2-u1-X20"}],"explanation":["설탕은 물에 녹아요.","모래는 걸러요.","물을 증발시켜요."]}'::jsonb),
('g5_2_sci_u1_review_d#20','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C16',3,'mc','auto','바다반 캠프 일지 ⑥·⑦의 장치들이 모두 지속가능한 삶을 돕는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X27','SC5-2-u1-X25','SC5-2-u1-X35']::text[],false,'{"seq":20,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"mc","stem":"바다반 캠프 일지 ⑥·⑦의 장치들이 모두 지속가능한 삶을 돕는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"깨끗한 물과 공기를 얻고 자원을 다시 써 한정된 자원과 환경을 지키기 때문이다","correct":true},{"t":"물질을 새 물질로 바꾸어 주기 때문이다","mis":"SC5-2-u1-X27"},{"t":"실험실에서만 쓰여 생활과 관계없기 때문이다","mis":"SC5-2-u1-X25"},{"t":"편하기만 하면 되기 때문이다","mis":"SC5-2-u1-X35"}],"explanation":["물·공기를 깨끗이 해요.","자원을 다시 써요.","지속가능한 삶을 도와요."],"asset":{"type":"passage","lines":["캠프 쓰레기를 플라스틱·종이·캔으로 나누어 모았다.","선별장 영상 — 카메라가 달린 장치가 플라스틱·종이·유리를 골라 냈다.","모둠마다 오늘 본 장치 하나를 골라 포스터를 만들어 올렸다."],"title":"⑦ 넷째 날 — 분리배출과 포스터"}}'::jsonb),
('g5_2_sci_u1_review_d#21','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C20',3,'mc','auto','새활용과 혼합물의 분리가 이어지는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X27','SC5-2-u1-X32','SC5-2-u1-X31']::text[],false,'{"seq":21,"concept":"SC5-2-u1-C20","difficulty":3,"kind":"mc","stem":"새활용과 혼합물의 분리가 이어지는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"버려진 것들 가운데 쓸 수 있는 재료를 나누어 골라 모아야 새 쓰임을 찾을 수 있다","correct":true},{"t":"새활용은 물질의 성질을 바꾸는 일이다","mis":"SC5-2-u1-X27"},{"t":"새활용과 분리는 아무 관계가 없다","mis":"SC5-2-u1-X32"},{"t":"새활용은 물건을 녹여 섞는 일이다","mis":"SC5-2-u1-X31"}],"explanation":["재료를 나눠 골라요.","그래야 쓸 수 있어요.","분리와 이어져요."]}'::jsonb),
('g5_2_sci_u1_review_d#22','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C21',3,'blank','auto','혼합물의 분리 정리판에서 ㉠에 들어갈 말은 어느 것인가요?',ARRAY['SC5-2-u1-X33','SC5-2-u1-X08']::text[],false,'{"seq":22,"concept":"SC5-2-u1-C21","difficulty":3,"kind":"blank","stem":"혼합물의 분리 정리판에서 ㉠에 들어갈 말은 어느 것인가요?","options":[{"t":"알갱이의 크기","correct":true},{"t":"물에 녹는 성질","mis":"SC5-2-u1-X33"},{"t":"알갱이의 색깔","mis":"SC5-2-u1-X08"},{"t":"위에 뜨는 성질","mis":"SC5-2-u1-X33"}],"explanation":["모래와 자갈 줄이에요.","체를 써요.","크기 차이예요."],"asset":{"type":"passage","lines":["모래와 자갈 — (㉠) 차이 — 체","물과 기름 — 섞이지 않고 위에 뜸 — (㉡)·흡착포","소금과 모래 — 물에 녹는지 — 거름 → (㉢)"],"title":"혼합물의 분리 정리판"}}'::jsonb),
('g5_2_sci_u1_review_d#23','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C4',4,'mc','auto','혼합물을 분리할 수 있어서 우리 삶이 달라진 점을 바다반 캠프 일지로 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X25','SC5-2-u1-X27','SC5-2-u1-X07']::text[],false,'{"seq":23,"concept":"SC5-2-u1-C4","difficulty":4,"kind":"mc","stem":"혼합물을 분리할 수 있어서 우리 삶이 달라진 점을 바다반 캠프 일지로 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"섬 마을은 바닷물로 마실 물을 얻고, 쓰레기는 나누어 자원으로 다시 쓰며, 소금과 깨끗한 공기도 얻는다","correct":true},{"t":"분리는 캠프 놀이일 뿐 삶과는 관계없다","mis":"SC5-2-u1-X25"},{"t":"분리하면 물질이 새로 바뀌어 편해졌을 뿐이다","mis":"SC5-2-u1-X27"},{"t":"주변 물질은 모두 혼합물이라서 분리할 수밖에 없다","mis":"SC5-2-u1-X07"}],"explanation":["마실 물을 얻어요.","자원을 다시 써요.","삶을 지켜요."]}'::jsonb),
('g5_2_sci_u1_review_d#24','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C12',4,'essay','teacher','바다반 캠프 일지 ④를 보고 모래가 섞인 바닷물에서 모래와 소금을 각각 얻은 과정을 차례대로 쓰고, 각 단계에서 이용한 성질을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u1-C12","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ④를 보고 모래가 섞인 바닷물에서 모래와 소금을 각각 얻은 과정을 차례대로 쓰고, 각 단계에서 이용한 성질을 쓰세요.","answer_guide":{"answer":"예: 거름 장치로 거르니 물에 녹지 않는 모래는 거름종이 위에 남고, 물에 녹은 소금은 물과 함께 빠져나갔다. 빠져나간 소금물을 증발 접시에 담아 약하게 가열하니 물이 증발하고 소금이 남았다. 소금은 물에 녹고 모래는 녹지 않는 성질을 이용했다.","scoring_points":["거름 단계를 썼는가","증발 단계를 썼는가","이용한 성질을 썼는가"]},"explanation":["거름이 먼저예요.","증발이 나중이에요.","녹는지로 나눠요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb),
('g5_2_sci_u1_review_d#25','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C20',4,'essay','teacher','바다반 캠프 일지 ⑧을 보고 뚜껑 벽화가 새활용인 까닭을 쓰고, 벽화를 만들 때 이 단원에서 배운 「나누기」가 어떻게 쓰였는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u1-C20","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ⑧을 보고 뚜껑 벽화가 새활용인 까닭을 쓰고, 벽화를 만들 때 이 단원에서 배운 「나누기」가 어떻게 쓰였는지 쓰세요.","answer_guide":{"answer":"예: 뚜껑을 녹이거나 부수지 않고 아이디어를 더해 「바다반」 글자 벽화라는 새 가치를 만들었으므로 새활용이다. 뚜껑을 다른 쓰레기에서 골라 모으고, 씻은 뒤 색깔별로 나누어 모아 원하는 색으로 글자를 꾸몄다.","scoring_points":["새활용인 까닭을 썼는가","골라 모으고 색깔별로 나눈 과정을 썼는가","재활용과의 차이가 드러나는가"]},"explanation":["녹이지 않았어요.","나누어 모았어요.","새 가치를 만들었어요."],"asset":{"type":"passage","lines":["캠프 동안 모은 페트병 뚜껑을 씻어 색깔별로 나누었다.","뚜껑을 녹이지 않고 그대로 붙여 「바다반」 글자 벽화를 만들었다.","마지막으로 캠프에서 나눈 혼합물을 정리판에 적었다."],"title":"⑧ 마지막 날 — 뚜껑 벽화와 정리판"}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SC5-2-u3-C1','sci',5,2,'u3',1,'열 변색 붙임딱지와 따뜻함 — 체온에서 변하는 열 변색 붙임딱지는 따뜻한 손을 대었다 떼면 색깔이 바뀌거나 투명해짐 · 문지르지 않고 대고 있기만 해도 변하고, 따뜻한 물이 든 컵에 대도 변함 · 손이 학용품보다 더 따뜻하기 때문이고, 따뜻함이 사라지면 서서히 원래대로 돌아옴 · 색이 바뀌는 컵·아기 숟가락처럼 따뜻한 정도를 눈으로 알려 주는 물건에 쓰임',ARRAY['[6과07-01] 온도를 측정하는 까닭을 알고, 온도계를 사용하여 여러 가지 물체의 온도를 측정할 수 있다.']::text[],1),
('SC5-2-u3-C2','sci',5,2,'u3',2,'온도와 온도의 단위 — 물체의 따뜻하거나 차가운 정도를 온도로 나타냄 · 단위는 °C이고 「섭씨도」라고 읽음(19.8 °C — 섭씨 십구 점 팔 도) · 온도는 무게·부피·길이와 다른 것',ARRAY['[6과07-01] 온도를 측정하는 까닭을 알고, 온도계를 사용하여 여러 가지 물체의 온도를 측정할 수 있다.']::text[],2),
('SC5-2-u3-C3','sci',5,2,'u3',2,'여러 가지 온도계 바르게 쓰기 — 탐침 온도계: 탐침을 액체나 물체 속에 넣고, 컵 벽·바닥에 닿지 않게 하며 숫자가 멈추면 읽음 · 알코올 온도계: 빨간 액체 기둥 끝을 눈높이에서 읽고 공기·액체 온도를 잼 · 적외선 온도계: 물체 표면을 겨누어 빠르게 재되 사람 눈을 향하지 않게 하고, 금속·거울처럼 빛을 반사하는 물체는 재기 어려움 · 상황에 맞는 온도계를 고름',ARRAY['[6과07-01] 온도를 측정하는 까닭을 알고, 온도계를 사용하여 여러 가지 물체의 온도를 측정할 수 있다.']::text[],3),
('SC5-2-u3-C4','sci',5,2,'u3',2,'온도를 재는 까닭 — 손으로 느끼는 따뜻하고 차가운 정도는 사람마다·상황마다 달라 정확하지 않음 · 온도계로 재면 누구나 같게, 정확하게 알 수 있음 · 체온 재기·요리·온실 식물 기르기처럼 알맞은 온도를 맞추는 데 쓰임 · 열화상 사진기는 온도를 색깔로 보여 줌',ARRAY['[6과07-01] 온도를 측정하는 까닭을 알고, 온도계를 사용하여 여러 가지 물체의 온도를 측정할 수 있다.']::text[],4),
('SC5-2-u3-C5','sci',5,2,'u3',3,'온도가 다른 두 물체의 온도 변화 — 따뜻한 물이 든 원통에 차가운 물이 든 캔을 넣고 1분마다 재면 따뜻한 물은 점점 낮아지고 차가운 물은 점점 높아짐 · 변화는 처음엔 크고 점점 작아지며, 시간이 충분히 지나면 두 물의 온도가 같아짐 · 차가운 물이 따뜻한 물보다 높아지지는 않음 · 꺾은선그래프로 나타내면 변화를 한눈에 봄',ARRAY['[6과07-02] 온도가 다른 두 물체가 접촉할 때 두 물체의 온도 변화를 관찰하고, 열의 이동을 설명할 수 있다.']::text[],5),
('SC5-2-u3-C6','sci',5,2,'u3',3,'열의 이동 방향 — 온도가 다른 두 물체가 닿으면 온도가 높은 물체에서 온도가 낮은 물체로 열이 이동해 온도가 변함 · 얼음 위 생선(생선 → 얼음), 이마의 냉각 시트(이마 → 시트), 얼음물에 헹군 면(면 → 얼음물) · 얼음을 만질 때 차가운 기운이 손으로 오는 것이 아니라 손의 열이 얼음으로 가서 손의 온도가 낮아짐',ARRAY['[6과07-02] 온도가 다른 두 물체가 접촉할 때 두 물체의 온도 변화를 관찰하고, 열의 이동을 설명할 수 있다.']::text[],6),
('SC5-2-u3-C7','sci',5,2,'u3',4,'고체에서 열의 이동 관찰 — 긴 구리판 한쪽 끝을 가열하면 가열한 곳에서 가까운 곳부터 붙임딱지 색깔이 차례로 변함 · ㄷ자 구리판에서도 열은 끊어진 틈을 건너뛰지 않고 구리판을 따라 돌아서 이동함 · 판 한가운데를 가열하면 가운데에서 바깥쪽으로 둥글게 퍼짐 · 붙임딱지는 열의 이동을 보여 주는 도우미',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],7),
('SC5-2-u3-C8','sci',5,2,'u3',4,'전도 — 온도가 높은 부분에서 온도가 낮은 부분으로 고체 물질을 따라 열이 이동하는 방식 · 종류가 다른 고체라도 맞닿아 있거나 이어져 있으면 열이 이동함(금속 프라이팬 → 달걀, 손 → 차가운 금속 손잡이) · 석쇠에 닿지 않은 고기 윗부분도 고기를 따라 전도로 익음',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],8),
('SC5-2-u3-C9','sci',5,2,'u3',4,'생활 속 전도 — 프라이팬·냄비는 열이 잘 이동하는 금속으로 만들어 바닥의 열이 음식까지 빨리 전해짐 · 손잡이는 나무·플라스틱으로 만들어 손이 데지 않게 함 · 뜨거운 국에 담근 금속 숟가락은 담긴 부분부터 손잡이 쪽으로 뜨거워짐 · 생활 도구는 전도를 이용하기도 막기도 함',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],9),
('SC5-2-u3-C10','sci',5,2,'u3',5,'액체에서 열의 이동 관찰 — 물이 든 사각 통 바닥의 잉크 아래에 뜨거운 물 컵을 넣으면 잉크가 위로 올라갔다가 옆으로 퍼지며 내려옴 · 데워진 물이 위로 올라가고 위의 물이 내려오기 때문 · 잉크는 물의 움직임을 보여 주는 도우미이고 열 자체는 눈에 보이지 않음',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],10),
('SC5-2-u3-C11','sci',5,2,'u3',5,'기체에서 열의 이동 관찰 — 아크릴 통 안 한가운데에 촛불을 두면 윗부분 붙임딱지 색깔이 먼저 변함 · 데워진 공기가 위로 올라가기 때문 · 찜기 맨 위 칸 만두까지 익는 것도 뜨거운 김이 위로 올라가기 때문',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],11),
('SC5-2-u3-C12','sci',5,2,'u3',5,'대류 — 액체나 기체를 가열하면 온도가 높아진 물질이 위로 올라가고 온도가 낮은 물질이 아래로 내려오며 열이 이동하는 방식 · 물질이 직접 움직이며 열을 옮기고, 이렇게 돌며 전체가 데워짐 · 고체에서 일어나는 전도와 다름',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],12),
('SC5-2-u3-C13','sci',5,2,'u3',5,'생활 속 대류 — 주전자 바닥만 가열해도 물이 위아래로 돌며 물 전체가 뜨거워짐 · 난방기는 방 아래쪽에 두면 데워진 공기가 올라가며 방 전체가 따뜻해짐 · 냉방기는 높은 곳에 달면 차가운 공기가 내려오며 방 전체가 시원해짐 · 기구의 자리를 정할 때 대류를 이용함',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],13),
('SC5-2-u3-C14','sci',5,2,'u3',6,'햇빛과 그늘의 온도 견주기 — 같은 온도의 검은색 판 두 장을 햇빛과 그늘에 두고 일정 시간 뒤 적외선 온도계로 재면 햇빛을 받은 판의 온도가 더 높아짐 · 판의 색·크기·처음 온도·시간은 같게 하고 놓는 곳만 다르게 함 · 판은 해와 닿아 있지 않은데도 온도가 높아짐 · 그늘이 시원한 것은 햇빛이 가려지기 때문',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],14),
('SC5-2-u3-C15','sci',5,2,'u3',6,'복사 — 빛에 의해 열이 이동하는 방식 · 물질이 닿거나 움직이지 않아도, 물질이 거의 없는 곳을 지나서도 열이 이동해 먼 해의 열이 지구까지 옴 · 난로 앞·보온 등 아래·모닥불 앞이 따뜻한 것도 복사 · 모닥불을 향한 얼굴만 뜨겁고 등은 차가움',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],15),
('SC5-2-u3-C16','sci',5,2,'u3',7,'세 가지 열의 이동 방식 견주기 — 전도는 고체 물질을 따라, 대류는 액체·기체가 직접 움직이며, 복사는 빛에 의해 열이 이동함 · 프라이팬 볶음(전도), 전기 주전자 물(대류), 열 전구·난로(복사) · 화덕·오븐·모닥불 캠프처럼 한 상황에서 세 방식이 함께 일어나기도 함',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],16),
('SC5-2-u3-C17','sci',5,2,'u3',8,'단열 — 열의 이동을 막는 것 · 보온병에 따뜻한 물을 담으면 오래 따뜻하게, 차가운 물이나 얼음을 담으면 오래 차갑게 지켜 줌 · 창문을 닫아 교실의 열을 지키는 것도 단열 · 단열이 잘되면 난방·냉방 에너지를 아낌',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],17),
('SC5-2-u3-C18','sci',5,2,'u3',8,'열의 이동 방식에 따라 막는 물건 — 주방 장갑·나무나 실리콘 냄비 받침(전도를 막음), 닫은 창문·문풍지(공기의 흐름, 곧 대류를 막음), 양산·그늘막(햇빛의 복사를 막음) · 아이스박스·보온 도시락·겹쳐 입은 옷·소방 보호 장비·집 벽 속 재료·이중창의 공기층도 단열 사례',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],18),
('SC5-2-u3-C19','sci',5,2,'u3',9,'단열재와 장치 설계 — 단열에 쓰는 재료를 단열재라고 함(뽁뽁이·스타이로폼·솜·이중 골판지, 주변 재료 재활용도 가능) · 단열재는 스스로 열을 만들거나 차갑게 하지 않고 열의 이동을 막아 처음 온도를 오래 지킴 · 따뜻한 것은 열이 빠져나가지 않게, 차가운 것은 열이 들어오지 않게 · 여러 겹 감싸고 틈 없이 뚜껑을 덮으며 쓰기 편한 점도 생각해 그림과 글로 설계함',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],19),
('SC5-2-u3-C20','sci',5,2,'u3',9,'장치 시험하고 고치기 — 장치에 물체를 넣고 시간 간격을 두고 온도를 재어 오랫동안 일정하게 유지되는지 확인함 · 같은 처음 온도·같은 시간이면 온도가 덜 변한 장치가 단열이 더 잘된 것 · 열이 새는 틈·얇은 곳을 찾아 막고 단열재를 더 겹쳐 고침 · 역할을 나누어 만들고 잘한 점을 나눔',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],20),
('SC5-2-u3-C21','sci',5,2,'u3',10,'첨단 단열 기술 — 아주 높은 온도를 유지해야 하는 인공 태양 연구 장치는 보온병과 비슷하게 단열함 · 이중벽 사이 공기를 빼고 단열재로 여러 번 감싸 전도와 대류를 막고, 이중벽 안쪽을 은으로 도금해 복사를 막음 · 단열 기술은 생활뿐 아니라 우주선·소방 장비 같은 첨단 기술에도 쓰임 · 공기가 거의 없는 우주에서는 태양의 복사를 가장 크게 막아야 함',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],21),
('SC5-2-u3-C22','sci',5,2,'u3',10,'열과 우리 생활 정리 — 온도는 온도계로 재고, 열은 온도가 높은 곳에서 낮은 곳으로 이동함 · 열은 전도·대류·복사로 이동하고 단열로 그 이동을 막음 · 상황을 보고 어디에서(고체·액체와 기체·빛) 어떤 방식으로 이동하는지 따진 뒤 막는 방법을 고름',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],22)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SC5-2-u3-X01','sci',5,'u3',ARRAY['SC5-2-u3-C1']::text[],'열 변색 붙임딱지는 손으로 문지르거나 세게 눌러야만 변한다고 여긴다','대고 있기만 해도 변해요'),
('SC5-2-u3-X02','sci',5,'u3',ARRAY['SC5-2-u3-C1']::text[],'한 번 변한 붙임딱지는 계속 그대로 남는다고 여긴다','서서히 원래대로'),
('SC5-2-u3-X03','sci',5,'u3',ARRAY['SC5-2-u3-C1']::text[],'붙임딱지가 변한 까닭을 따뜻함이 아닌 엉뚱한 것(입김의 세기·펜 색·차가운 손)에서 찾는다','손의 따뜻함 때문'),
('SC5-2-u3-X04','sci',5,'u3',ARRAY['SC5-2-u3-C4']::text[],'손으로 만져 보면 물체의 온도를 정확하게 알 수 있다고 여긴다','느낌은 사람마다 달라요'),
('SC5-2-u3-X05','sci',5,'u3',ARRAY['SC5-2-u3-C2']::text[],'°C를 「도씨」로 읽거나 온도에 단위를 빠뜨린다','섭씨 ○ 도'),
('SC5-2-u3-X06','sci',5,'u3',ARRAY['SC5-2-u3-C3']::text[],'온도계 쓰는 법을 놓친다(탐침이 바닥에 닿음·기둥을 비스듬히 읽음·적외선을 눈에 겨눔)','가운데 · 눈높이 · 눈 피하기'),
('SC5-2-u3-X07','sci',5,'u3',ARRAY['SC5-2-u3-C3']::text[],'상황에 맞지 않는 온도계를 고른다(반짝이는 금속을 적외선으로, 국 속을 겉면만)','무엇을 재나 먼저'),
('SC5-2-u3-X08','sci',5,'u3',ARRAY['SC5-2-u3-C2']::text[],'온도를 무게·부피·길이 같은 다른 양과 헷갈린다','따뜻하거나 차가운 정도'),
('SC5-2-u3-X09','sci',5,'u3',ARRAY['SC5-2-u3-C5']::text[],'온도가 다른 두 물체가 닿으면 한쪽 온도만 변한다고 여긴다','둘 다 변해요'),
('SC5-2-u3-X10','sci',5,'u3',ARRAY['SC5-2-u3-C5']::text[],'오래 두면 차가웠던 물이 따뜻했던 물보다 더 높아지거나, 두 온도가 끝내 같아지지 않는다고 여긴다','같아질 때까지'),
('SC5-2-u3-X11','sci',5,'u3',ARRAY['SC5-2-u3-C6']::text[],'열이 온도가 낮은 물체에서 높은 물체로 이동한다고 여긴다','높음 → 낮음'),
('SC5-2-u3-X12','sci',5,'u3',ARRAY['SC5-2-u3-C6']::text[],'차가운 물체의 냉기(차가운 기운)가 옮겨 가서 다른 물체가 차가워진다고 여긴다','열이 빠져나가서 차가워져요'),
('SC5-2-u3-X13','sci',5,'u3',ARRAY['SC5-2-u3-C5']::text[],'온도 변화 꺾은선그래프에서 선과 물을 바꾸어 읽거나 변화가 끝까지 같은 빠르기라고 읽는다','처음엔 크게 · 점점 작게'),
('SC5-2-u3-X14','sci',5,'u3',ARRAY['SC5-2-u3-C7']::text[],'고체를 가열하면 모든 곳이 한꺼번에, 또는 먼 곳부터 뜨거워진다고 여긴다','가까운 곳부터 차례로'),
('SC5-2-u3-X15','sci',5,'u3',ARRAY['SC5-2-u3-C7']::text[],'ㄷ자 구리판에서 열이 끊어진 틈을 건너뛰어 이동한다고 여긴다','판을 따라 돌아서'),
('SC5-2-u3-X16','sci',5,'u3',ARRAY['SC5-2-u3-C8']::text[],'종류가 다른 고체끼리는 맞닿아도 열이 이동하지 않는다고 여긴다','닿아 있으면 이동해요'),
('SC5-2-u3-X17','sci',5,'u3',ARRAY['SC5-2-u3-C8','SC5-2-u3-C12']::text[],'전도와 대류를 헷갈린다(물이 도는 것을 전도로, 고체를 따라 가는 것을 대류로)','고체 따라 ↔ 물질이 움직이며'),
('SC5-2-u3-X18','sci',5,'u3',ARRAY['SC5-2-u3-C9']::text[],'냄비 손잡이도 열이 잘 이동하는 금속이 좋다고 여기거나 손잡이 재료의 까닭을 거꾸로 안다','손잡이는 열이 잘 안 가게'),
('SC5-2-u3-X19','sci',5,'u3',ARRAY['SC5-2-u3-C10']::text[],'잉크나 붙임딱지의 움직임이 열 그 자체라고 여긴다(열이 눈에 보인다고)','잉크는 물의 움직임을 보여 줘요'),
('SC5-2-u3-X20','sci',5,'u3',ARRAY['SC5-2-u3-C10','SC5-2-u3-C11','SC5-2-u3-C12']::text[],'데워진 물이나 공기가 아래로 내려간다고 여긴다','데워지면 위로'),
('SC5-2-u3-X21','sci',5,'u3',ARRAY['SC5-2-u3-C11']::text[],'촛불을 둔 통에서 아랫부분이나 촛불 옆 붙임딱지부터 변한다고 여긴다','윗부분 먼저'),
('SC5-2-u3-X22','sci',5,'u3',ARRAY['SC5-2-u3-C12']::text[],'대류에서 물질은 가만히 있고 열만 이동한다고 여긴다','물질이 직접 움직여요'),
('SC5-2-u3-X23','sci',5,'u3',ARRAY['SC5-2-u3-C13']::text[],'난방기는 높은 곳에, 냉방기는 낮은 곳에 두어야 좋다고 여긴다','난방 아래 · 냉방 위'),
('SC5-2-u3-X24','sci',5,'u3',ARRAY['SC5-2-u3-C14']::text[],'햇빛에 둔 판과 그늘에 둔 판의 온도가 같거나 그늘 판이 더 높아진다고 여긴다','햇빛을 받은 판이 더 높아요'),
('SC5-2-u3-X25','sci',5,'u3',ARRAY['SC5-2-u3-C15']::text[],'열은 물질이 닿거나 움직여야만 이동한다고 여긴다(해의 열이 오는 길을 설명하지 못함)','빛에 의해서도 이동해요'),
('SC5-2-u3-X26','sci',5,'u3',ARRAY['SC5-2-u3-C15','SC5-2-u3-C16']::text[],'복사의 예와 전도·대류의 예를 바꾸어 고른다(숟가락이 뜨거워지는 것을 복사로)','빛으로 오나, 닿아서 오나'),
('SC5-2-u3-X27','sci',5,'u3',ARRAY['SC5-2-u3-C16']::text[],'한 상황에서는 열이 한 가지 방식으로만 이동한다고 여긴다','여러 방식이 함께'),
('SC5-2-u3-X28','sci',5,'u3',ARRAY['SC5-2-u3-C16']::text[],'전도·대류·복사의 특징을 바꾸어 짝짓는다(복사는 물질이 닿아야, 대류는 고체에서)','고체 · 액체와 기체 · 빛'),
('SC5-2-u3-X29','sci',5,'u3',ARRAY['SC5-2-u3-C17']::text[],'보온병은 따뜻한 것을 따뜻하게 지킬 때만 쓴다고 여긴다','차갑게도 지켜요'),
('SC5-2-u3-X30','sci',5,'u3',ARRAY['SC5-2-u3-C17']::text[],'단열을 열이 더 잘, 더 빨리 이동하게 하는 것으로 여긴다','단열은 막는 것'),
('SC5-2-u3-X31','sci',5,'u3',ARRAY['SC5-2-u3-C18']::text[],'단열 물건과 그 물건이 막는 열의 이동 방식을 바꾸어 짝짓는다(양산이 전도를, 주방 장갑이 복사를)','장갑 전도 · 창문 대류 · 양산 복사'),
('SC5-2-u3-X32','sci',5,'u3',ARRAY['SC5-2-u3-C19']::text[],'단열재가 스스로 물체를 따뜻하게(또는 차갑게) 만든다고 여긴다','막아서 지킬 뿐'),
('SC5-2-u3-X33','sci',5,'u3',ARRAY['SC5-2-u3-C19']::text[],'장치에 구멍·틈을 내거나 뚜껑을 열어 두어도 단열이 잘된다고 여긴다','틈이 열의 길'),
('SC5-2-u3-X34','sci',5,'u3',ARRAY['SC5-2-u3-C20']::text[],'장치 성능을 온도가 아닌 색·무게·모양으로 따지거나, 온도가 더 많이 변한 쪽이 잘된 것이라고 여긴다','시간마다 온도 · 덜 변한 쪽'),
('SC5-2-u3-X35','sci',5,'u3',ARRAY['SC5-2-u3-C21']::text[],'단열 기술은 보온병이나 옷처럼 생활 속에서만 쓰인다고 여긴다','첨단 기술에도 써요'),
('SC5-2-u3-X36','sci',5,'u3',ARRAY['SC5-2-u3-C21']::text[],'첨단 단열 장치의 방법과 막는 방식을 바꾸어 짝짓는다(은 도금이 전도를, 공기를 뺀 것이 복사를)','공기 빼기 전도·대류 · 은 도금 복사')
